const state={me:null,projects:[],project:null,page:'queue',items:[],locale:localStorage.pbLocale||'zh',task:null,drawer:null,lastFocus:null};
function t(key,variables={}){const value=(messages[state.locale]||messages.zh)[key]||messages.en[key]||key;return Object.entries(variables).reduce((text,[name,replacement])=>text.replaceAll(`{${name}}`,String(replacement)),value)}
function syncDocumentLocale(){document.documentElement.lang=state.locale==='zh'?'zh-CN':'en';const skip=$('.skip-link');if(skip)skip.textContent=t('skipToWorkspace');const description=document.querySelector('meta[name="description"]');if(description)description.content=state.locale==='zh'?'ProjectBoard 成员与 Agent 协作任务队列':'ProjectBoard member and Agent work queue'}
async function api(path,options={}){const multipart=options.body instanceof FormData;const headers={...(multipart?{}:{'Content-Type':'application/json'}),...(options.headers||{})};if(!['GET','HEAD'].includes(options.method||'GET')){const csrf=document.cookie.split('; ').find(x=>x.startsWith('pb_csrf='))?.split('=')[1];if(csrf)headers['X-CSRF-Token']=decodeURIComponent(csrf)}const response=await fetch(path,{...options,headers});let value=null;const type=response.headers.get('content-type')||'';if(type.includes('json'))value=await response.json();if(!response.ok)throw new Error(value?.error?.message||response.statusText);return value}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2600)}
function escapeHTML(value=''){return String(value).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function field(label,name,type='text',value='',extra=''){return `<label class="field"><span>${escapeHTML(label)}</span><input name="${name}" type="${type}" value="${escapeHTML(value)}" ${extra}></label>`}
function area(label,name,value='',extra=''){return `<label class="field"><span>${escapeHTML(label)}</span><textarea name="${name}" ${extra}>${escapeHTML(value)}</textarea></label>`}
function badge(text,kind=''){return `<span class="badge ${kind}">${escapeHTML(text)}</span>`}
function header(title,description,actions='',tools=''){return `<header class="page-head"><div class="page-title"><div><h1>${escapeHTML(title)}</h1><p>${escapeHTML(description)}</p></div><div class="page-actions">${actions}</div></div>${tools?`<div class="tools">${tools}</div>`:''}</header>`}
async function boot(){syncDocumentLocale();try{state.me=await api('/api/me');await loadProjects();renderShell()}catch{renderLogin()}}
function localeControl(){return `<button class="button locale-control" id="locale" type="button" aria-label="${t(state.locale==='zh'?'switchToEnglish':'switchToChinese')}">${state.locale==='zh'?'EN':'中文'}</button>`}
function wireLocaleControl(){const control=$('#locale');if(control)control.onclick=()=>{state.locale=state.locale==='zh'?'en':'zh';localStorage.pbLocale=state.locale;syncDocumentLocale();state.me?renderShell():renderLogin()}}
function renderLogin(){syncDocumentLocale();$('#app').innerHTML=`<main class="login-screen"><section class="login-panel"><div class="login-brand-row"><div class="brand"><span class="brand-mark">PB</span><span>${t('loginBrand')}</span></div>${localeControl()}</div><div class="login-copy"><h1>${t('loginTitle')}</h1><p>${t('loginNote')}</p></div><form class="login-form" id="loginForm">${field(t('username'),'username','text','admin','required autocomplete="username"')}${field(t('password'),'password','password','','required autocomplete="current-password"')}<div class="form-error" hidden></div><button class="button primary" type="submit">${t('signIn')} ${icon('chevron')}</button></form></section><aside class="login-art"><div class="route-diagram"><span>${t('discuss')}</span><i></i><span>${t('execute')}</span><i></i><span>${t('accept')}</span></div></aside></main>`;wireLocaleControl();$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=$('button[type=submit]',form),error=$('.form-error',form);button.disabled=true;error.hidden=true;try{const result=await api('/api/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});state.me=result.user;await loadProjects();renderShell()}catch(x){error.textContent=x.message;error.hidden=false}finally{button.disabled=false}})}
async function loadProjects(){state.projects=await api('/api/projects');const saved=localStorage.pbProject;state.project=state.projects.find(p=>p.id===saved)||state.projects[0]||null;if(state.project)localStorage.pbProject=state.project.id}
const nav1=[['queue','list'],['members','users'],['agents','bot'],['settings','settings']],nav2=[['users','users'],['projects','grid'],['activity','activity'],['globalSettings','settings']],navButton=([page,i])=>`<button data-page="${page}" class="${state.page===page?'active':''}">${icon(i)}<span>${t(page)}</span></button>`;
function renderShell(){syncDocumentLocale();$('#app').innerHTML=`<div class="shell"><header class="mast"><div class="brand"><span class="brand-mark">PB</span><span>ProjectBoard</span></div><div class="mast-actions">${localeControl()}</div></header><div class="workspace-grid"><aside class="rail"><button class="project-switch" id="projectSwitch"><span class="project-mark">${state.project?escapeHTML(state.project.key.slice(0,2).toUpperCase()):'--'}</span><span><strong>${escapeHTML(state.project?.name||t('noProjects'))}</strong><small>${escapeHTML(state.project?.repositoryUrl||t('projectSetup'))}</small></span>${icon('chevron')}</button><span class="rail-label">${t('workspace')}</span><nav class="nav">${nav1.map(navButton).join('')}</nav><span class="rail-label">${t('system')}</span><nav class="nav">${nav2.map(navButton).join('')}</nav><span class="rail-label">${t('profile')}</span><nav class="nav"><button data-page="account" class="${state.page==='account'?'active':''}">${icon('user')}<span>${t('account')}</span></button></nav><div class="rail-foot">${t('footerRuntime')}<br>${t('footerEmbedded')}</div></aside><main class="workspace" id="workspace"></main></div></div><div class="drawer-backdrop" id="drawerBackdrop"></div><aside class="drawer" id="drawer" role="dialog" aria-modal="true" aria-hidden="true"></aside>`;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));wireLocaleControl();$('#projectSwitch').onclick=projectPicker;$('#drawerBackdrop').onclick=closeDrawer;document.addEventListener('keydown',escapeDrawer,{once:true});renderPage()}
function escapeDrawer(e){if(e.key==='Escape')closeDrawer();else document.addEventListener('keydown',escapeDrawer,{once:true})}
function navigate(page){state.page=page;state.task=null;renderShell()}
async function renderPage(){const root=$('#workspace');root.innerHTML=`<div class="loading">${t('loading')}</div>`;try{if(state.page==='queue')await renderQueue();else if(state.page==='members')await renderMembers();else if(state.page==='agents')await renderAgents();else if(state.page==='settings')await renderSettings();else if(state.page==='users')await renderUsers();else if(state.page==='projects')await renderProjects();else if(state.page==='activity')await renderActivity();else if(state.page==='globalSettings')await renderSystemSettings();else await renderAccount()}catch(e){root.innerHTML=header(t('loadFailed'),t('loadFailedNote'))+`<div class="content"><div class="form-error">${escapeHTML(e.message)}</div></div>`}}
async function renderQueue(){if(!state.project){$('#workspace').innerHTML=header(t('queue'),t('noProjectsNote'),`<button class="button primary" id="createProject">${icon('plus')}${t('createProject')}</button>`)+emptyState(t('noProjects'),t('noProjectsNote'));$('#createProject').onclick=projectForm;return}state.items=await api(`/api/work-items?projectId=${encodeURIComponent(state.project.id)}`);if(state.task){await renderTask();return}const actions=`<button class="button primary" id="newItem">${icon('plus')}${t('createItem')}</button>`;const tools=`<label class="search">${icon('search')}<input id="queueSearch" placeholder="${t('search')}"></label>${badge(t('itemsCount',{count:state.items.length}))}`;const rows=state.items.map(item=>`<button class="work-row" data-id="${item.id}"><i class="priority-bar ${item.priority}"></i><span class="work-title"><strong>${escapeHTML(item.title)}</strong><small>${item.id} / ${escapeHTML(item.target_branch)} / V${item.version}</small></span><span class="row-meta">${item.blocked_at?badge(t('blocked'),'danger'):''}${badge(t(item.stage),item.stage==='execution'||item.stage==='acceptance'?'signal':'')}</span></button>`).join('');$('#workspace').innerHTML=header(t('queue'),`${state.project.name} / ${state.project.repositoryUrl}`,actions,tools)+`<div class="content">${rows?`<section class="queue-group"><div class="group-label">${t('currentRoute',{count:state.items.length})}</div>${rows}</section>`:emptyState(t('empty'),t('emptyNote'))}</div>`;$('#newItem').onclick=workItemForm;document.querySelectorAll('.work-row').forEach(row=>row.onclick=()=>{state.task=row.dataset.id;renderQueue()});$('#queueSearch').oninput=e=>document.querySelectorAll('.work-row').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(e.target.value.toLowerCase()))}
function emptyState(title,note){return `<section class="empty"><div class="empty-inner"><div class="empty-index">00</div><h2>${escapeHTML(title)}</h2><p>${escapeHTML(note)}</p></div></section>`}
const stages=['todo','discussion','execution','acceptance','completed','order_closed'];
async function renderTask(){const item=await api(`/api/work-items/${state.task}`);const index=stages.indexOf(item.stage);const track=stages.map((s,i)=>`<div class="stage ${i<index?'done':i===index?'current':''}">${t(s)}</div>`).join('');const events=(item.conversation||[]).map(e=>{const p=e.payload||JSON.parse(e.payload_json||'{}');return `<article class="event"><div class="event-meta">${escapeHTML(e.kind)}<br>${escapeHTML(e.created_at||'')}</div><div class="event-body">${escapeHTML(p.markdown||p.noteMarkdown||p.reason||JSON.stringify(p,null,2))}</div></article>`}).join('');$('#workspace').innerHTML=`<header class="page-head task-head"><button class="back" id="back">${icon('chevron')} ${t('queue')}</button><div class="page-title"><div><h1>${escapeHTML(item.title)}</h1><p>${item.id} / ${t('version',{version:item.version})} / ${escapeHTML(item.target_branch)}</p></div><div class="page-actions"><button class="button" id="message">${t('addMessage')}</button><button class="button" id="stageAction">${t('stageAction')}</button></div></div><div class="stage-wrap"><div class="stage-track">${track}</div></div></header><div class="content task-body"><div class="task-summary"><section class="prose"><h2>${t('workItem')}</h2><p>${escapeHTML(item.description_markdown||t('noDescription'))}</p><h2>${t('acceptanceCriteria')}</h2><p>${escapeHTML(item.acceptance_criteria_markdown||t('noCriteria'))}</p></section><aside class="settings-section"><div class="kv"><div><dt>${t('stage')}</dt><dd>${t(item.stage)}</dd></div><div><dt>${t('priority')}</dt><dd>${t(item.priority)}</dd></div><div><dt>${t('assignee')}</dt><dd>${t(item.assignee_kind||'unassigned')}</dd></div><div><dt>${t('blocked')}</dt><dd>${item.blocked_at?t('yes'):t('no')}</dd></div></div></aside></div><section class="conversation"><h2>${t('continuousConversation')}</h2>${events||`<p>${t('noEvents')}</p>`}</section></div>`;$('#back').onclick=()=>{state.task=null;renderQueue()};$('#message').onclick=()=>messageForm(item);$('#stageAction').onclick=()=>stageForm(item)}
function openDrawer(title,body,onReady){state.lastFocus=document.activeElement;const drawer=$('#drawer'),back=$('#drawerBackdrop');drawer.classList.remove('agent-ssh-drawer');drawer.innerHTML=`<header class="drawer-head"><h2>${escapeHTML(title)}</h2><button class="icon-button" id="closeDrawer" aria-label="${t('close')}">${icon('x')}</button></header>${body}`;drawer.classList.add('open');back.classList.add('open');drawer.setAttribute('aria-hidden','false');$('#closeDrawer').onclick=closeDrawer;onReady?.(drawer);setTimeout(()=>drawer.querySelector('input,button,select,textarea')?.focus(),20)}
function closeDrawer(){clearInterval(state.gitPoll);state.gitPoll=null;const drawer=$('#drawer');if(!drawer)return;drawer.classList.remove('open');$('#drawerBackdrop')?.classList.remove('open');drawer.setAttribute('aria-hidden','true');state.lastFocus?.focus()}
function wireForm(selector,submit){const form=$(selector);form.onsubmit=async e=>{e.preventDefault();const button=$('button[type=submit]',form),error=$('.form-error',form);button.disabled=true;error.hidden=true;try{await submit(Object.fromEntries(new FormData(form)));closeDrawer();await loadProjects();await renderPage()}catch(x){error.textContent=x.message;error.hidden=false}finally{button.disabled=false}}}
function formShell(fields,note=''){return `${note?`<p class="drawer-note">${escapeHTML(note)}</p>`:''}<form class="form" id="drawerForm">${fields}<div class="form-error" hidden></div><button class="button primary" type="submit">${t('save')}</button></form>`}
async function workItemForm(){const [members,agents]=await Promise.all([api(`/api/projects/${state.project.id}/members`),api(`/api/projects/${state.project.id}/agents`)]);const choices=[...members.filter(x=>x.role&&x.status==='active').map(x=>`<option value="human:${x.id}">${escapeHTML(x.displayName)} / ${t('human')}</option>`),...agents.filter(x=>x.enabled&&x.status==='active').map(x=>`<option value="agent:${x.id}">${escapeHTML(x.name)} / Agent</option>`)].join('');const fields=field(t('title'),'title','text','','required')+area(t('description'),'descriptionMarkdown')+area(t('acceptanceCriteria'),'acceptanceCriteriaMarkdown','','required')+`<label class="field"><span>${t('priority')}</span><select name="priority"><option value="medium">${t('medium')}</option><option value="urgent">${t('urgent')}</option><option value="high">${t('high')}</option><option value="low">${t('low')}</option></select></label><label class="field"><span>${t('assignee')}</span><select name="assignee" required><option value="">${t('selectExecutor')}</option>${choices}</select></label>`;openDrawer(t('createItem'),formShell(fields,t('assignmentStartsDiscussion')),()=>wireForm('#drawerForm',d=>{const [assigneeKind,assigneeId]=d.assignee.split(':');delete d.assignee;return api('/api/work-items',{method:'POST',body:JSON.stringify({...d,assigneeKind,assigneeId,projectId:state.project.id,requestId:crypto.randomUUID()})})}))}
function messageForm(item){openDrawer(t('continueConversation'),formShell(area(t('message'),'markdown','','required')),()=>wireForm('#drawerForm',d=>api(`/api/work-items/${item.id}/messages`,{method:'POST',body:JSON.stringify({...d,requestId:crypto.randomUUID(),expectedVersion:item.version})})))}
function stageForm(item){let fields='';let path='';if(item.blocked_at){path='unblock';fields=`<p class="drawer-note">${t('clearBlockedNote')}</p>`}else if(item.stage==='discussion'){path='discussion-conclusions';fields=area(t('goal'),'goalMarkdown','','required')+area(t('scope'),'scopeMarkdown','','required')+area(t('outOfScope'),'outOfScopeMarkdown')+area(t('implementationPlan'),'implementationPlanMarkdown','','required')+area(t('acceptanceCriteria'),'acceptanceCriteriaMarkdown','','required')+area(t('risks'),'risksMarkdown')}else if(item.stage==='execution'){path='submit-execution';fields=area(t('summary'),'summaryMarkdown','','required')+field(t('commitSHA'),'commit')+area(t('changedFiles'),'files')+`<input type="hidden" name="pushed" value="true"><input type="hidden" name="worktreeClean" value="true"><input type="hidden" name="forbiddenPathsClean" value="true">`}else if(item.stage==='acceptance'){path='acceptance-attempts';fields=`<label class="field"><span>${t('outcome')}</span><select name="outcome"><option value="pass">${t('pass')}</option><option value="changes_requested">${t('changesRequested')}</option><option value="scope_unclear">${t('scopeUnclear')}</option><option value="abandon">${t('abandon')}</option></select></label>`+area(t('note'),'noteMarkdown','','required')}else{path='block';fields=area(t('blockReason'),'reason','','required')}openDrawer(t('stageAction'),formShell(fields),()=>wireForm('#drawerForm',d=>{const body={...d,requestId:crypto.randomUUID(),expectedVersion:item.version};if(path==='submit-execution'){body.commits=d.commit?[d.commit]:[];body.changedFiles=d.files?d.files.split(/\r?\n/).filter(Boolean):[];body.validations=[];body.remainingRisksMarkdown='';delete body.commit;delete body.files;body.pushed=true;body.worktreeClean=true;body.forbiddenPathsClean=true}return api(`/api/work-items/${item.id}/${path}`,{method:'POST',body:JSON.stringify(body)})}))}
function projectForm(){openDrawer(t('createProject'),formShell(field(t('name'),'name','text','','required')+field(t('projectKey'),'key','text','','required pattern="[A-Za-z][A-Za-z0-9-]{1,19}"')+field(t('repositoryURL'),'repositoryUrl','url','','required')),()=>wireForm('#drawerForm',d=>api('/api/projects',{method:'POST',body:JSON.stringify(d)})))}
function projectPicker(){const options=state.projects.map(p=>`<button class="work-row" data-project="${p.id}"><i class="priority-bar"></i><span class="work-title"><strong>${escapeHTML(p.name)}</strong><small>${escapeHTML(p.repositoryUrl)}</small></span>${p.id===state.project?.id?badge(t('current'),'signal'):''}</button>`).join('');openDrawer(t('switchProject'),`<div class="table">${options||emptyState(t('noProjects'),t('noProjectsNote'))}</div><p><button class="button primary" id="newProjectInPicker">${icon('plus')}${t('createProject')}</button></p>`,drawer=>{drawer.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>{state.project=state.projects.find(p=>p.id===b.dataset.project);localStorage.pbProject=state.project.id;closeDrawer();renderShell()});$('#newProjectInPicker').onclick=projectForm})}
async function renderMembers(){if(!state.project)return renderQueue();const data=await api(`/api/projects/${state.project.id}/members`);const rows=data.map(x=>`<button class="table-row action management-row" data-member="${x.id}"><span><strong>${escapeHTML(x.displayName)}</strong><small>@${escapeHTML(x.username)}</small></span><span>${t(x.status)}</span><span>${t(x.systemRole)}</span><span class="row-end">${x.role?badge(t(x.role),'signal'):badge(t('notMember'))}${icon('chevron')}</span></button>`).join('');$('#workspace').innerHTML=header(t('members'),t('membersDescription'))+`<div class="content"><div class="table">${rows}</div></div>`;document.querySelectorAll('[data-member]').forEach(row=>row.onclick=()=>memberSettings(data.find(x=>x.id===row.dataset.member)))}
function memberSettings(member){const hasAccess=Boolean(member.role);const roleField=`<label class="field"><span>${t('projectRole')}</span><select name="role"><option value="developer" ${member.role==='developer'?'selected':''}>${t('developer')}</option><option value="viewer" ${member.role==='viewer'?'selected':''}>${t('viewer')}</option></select></label>`;openDrawer(t('memberSettings'),`<section class="entity-summary"><span class="user-avatar large">${escapeHTML(member.displayName.trim().slice(0,1).toUpperCase()||'?')}</span><div><span class="eyebrow">${t('humanAccount')} / @${escapeHTML(member.username)}</span><h3>${escapeHTML(member.displayName)}</h3><div>${badge(t(member.status),member.status==='disabled'?'danger':'')} ${badge(t(member.systemRole))}</div></div></section>${formShell(roleField,hasAccess?t('memberRoleNote'):t('addMemberNote'))} ${hasAccess?`<section class="drawer-section"><button class="button danger" id="removeMember" type="button">${t('removeFromProject')}</button></section>`:''}`,()=>{wireForm('#drawerForm',d=>api(`/api/projects/${state.project.id}/members${hasAccess?`/${member.id}`:''}`,{method:hasAccess?'PATCH':'POST',body:JSON.stringify(hasAccess?d:{userId:member.id,...d})}));const remove=$('#removeMember');if(remove)remove.onclick=async()=>{remove.disabled=true;try{await api(`/api/projects/${state.project.id}/members/${member.id}`,{method:'DELETE',body:'{}'});closeDrawer();toast(t('memberRemoved'));renderMembers()}catch(error){toast(error.message);remove.disabled=false}}})}
async function renderAgents(){if(!state.project)return renderQueue();const data=await api(`/api/projects/${state.project.id}/agents`);const actions=`<button class="button primary" id="newAgent">${icon('plus')}${t('createAgent')}</button>`;const rows=data.map(x=>`<button class="table-row action management-row" data-agent="${x.id}"><span><strong>${escapeHTML(x.name)}</strong><small>${escapeHTML(x.purpose)}</small></span><span>${t(x.status)}</span><span>${t('agentConnection')}</span><span class="row-end">${badge(t(x.enabled?'enabled':'disabled'),x.enabled?'signal':'')}${icon('chevron')}</span></button>`).join('');$('#workspace').innerHTML=header(t('agents'),t('agentsDescription'),actions)+`<div class="content"><div class="table">${rows}</div></div>`;$('#newAgent').onclick=agentForm;document.querySelectorAll('[data-agent]').forEach(row=>row.onclick=()=>agentSettings(data.find(x=>x.id===row.dataset.agent)))}
async function renderSystemSettings(){const settings=await api('/api/system/settings');const value=settings.publicUrl||location.origin;$('#workspace').innerHTML=header(t('globalSettings'),'One address for provider callbacks across every project.')+`<div class="content system-settings"><section class="settings-section"><h2>ProjectBoard address</h2><p>Used only when GitHub or UnsupportedProvider redirects your browser back to ProjectBoard. Localhost is supported.</p><form class="form" id="systemSettingsForm">${field('ProjectBoard URL','publicUrl','url',value,'required')}<div class="form-error" hidden></div><button class="button primary" type="submit">${t('save')}</button></form></section><section class="settings-section"><h2>Git synchronization</h2><div class="kv"><div><dt>Mode</dt><dd>ON DEMAND</dd></div><div><dt>Webhook</dt><dd>DISABLED</dd></div></div><p>ProjectBoard queries recent commits only when a person clicks Sync recent commits or an active Codex notifies the project.</p></section></div>`;$('#systemSettingsForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),error=$('.form-error',form);button.disabled=true;error.hidden=true;try{await api('/api/system/settings',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(form)))});toast('System settings saved');renderSystemSettings()}catch(x){error.textContent=x.message;error.hidden=false;button.disabled=false}}}
async function renderSettings(){if(!state.project)return renderQueue();let grant=null;try{grant=await api(`/api/projects/${state.project.id}/repository-grant`)}catch{}const actions=`<button class="button" id="editProject">Edit settings</button>${grant?`<button class="button" id="syncCommits">${icon('activity')}Sync recent commits</button>`:''}<button class="button primary" id="gitGrant">${icon('git')}${grant?'Change Git access':'Automatic Git setup'}</button>`;$('#workspace').innerHTML=header(t('settings'),'Repository rules and independently approved access.',actions)+`<div class="content settings-grid"><section class="settings-section"><h2>Repository authorization</h2>${grant?`<div class="kv"><div><dt>Provider</dt><dd>${escapeHTML(grant.provider)}</dd></div><div><dt>Authorization</dt><dd>${escapeHTML(grant.authorizationName)}</dd></div><div><dt>Repository</dt><dd>${escapeHTML(grant.repositoryName)}</dd></div><div><dt>Access</dt><dd>${escapeHTML(grant.accessLevel)}</dd></div><div><dt>Commit sync</dt><dd>ON DEMAND</dd></div></div>`:'<p>No repository grant. Use Automatic Git setup to connect a provider, list its repositories, then confirm this project’s exact access.</p>'}</section><section class="settings-section"><h2>Repository & branches</h2><div class="kv"><div><dt>Repository URL</dt><dd>${escapeHTML(state.project.repositoryUrl)}</dd></div><div><dt>Default target</dt><dd>${escapeHTML(state.project.defaultTargetBranch)}</dd></div><div><dt>Allowed</dt><dd>${escapeHTML((state.project.allowedTargetBranches||[]).join(', '))}</dd></div><div><dt>Config version</dt><dd>${state.project.configVersion}</dd></div></div></section><section class="settings-section"><h2>Execution policy</h2><p>Codex pushes only controlled task branches. After a push, an active Codex can notify ProjectBoard to query recent commits.</p></section><section class="settings-section"><h2>Credential policy</h2><p>No Webhook listener or background polling is used. Provider secrets remain encrypted, and every manual or Codex-triggered sync is project-scoped and audited.</p></section></div>`;$('#editProject').onclick=()=>editProjectForm(state.project);$('#gitGrant').onclick=grantForm;const sync=$('#syncCommits');if(sync)sync.onclick=async()=>{sync.disabled=true;try{const result=await api(`/api/projects/${state.project.id}/sync-commits`,{method:'POST',body:'{}'});toast(`Fetched ${result.fetched}; attached ${result.inserted} commit${result.inserted===1?'':'s'}`)}catch(error){toast(error.message)}finally{sync.disabled=false}}}
function editProjectForm(p){openDrawer(t('editProject'),formShell(field(t('name'),'name','text',p.name,'required')+field(t('repositoryURL'),'repositoryUrl','url',p.repositoryUrl)+field(t('defaultTargetBranch'),'defaultTargetBranch','text',p.defaultTargetBranch)+area(t('allowedBranches'),'allowed',p.allowedTargetBranches.join('\n'))),()=>wireForm('#drawerForm',d=>api(`/api/projects/${p.id}`,{method:'PATCH',body:JSON.stringify({...d,allowedTargetBranches:d.allowed.split(/\s+/).filter(Boolean)})})))}
async function grantForm(){const [configuration,settings,auths]=await Promise.all([api('/api/git/connections'),api('/api/git/provider-settings'),api('/api/provider-authorizations')]);const providerButton=(provider,label)=>{const configured=configuration[provider]?.configured;const setupLabel=t(provider==='github'?'setupGitHub':'setupUnsupportedProvider');const setupCopy=t(provider==='github'?'githubSetupCopy':'unsupportedSetupCopy');return `<button class="connection-provider" type="button" ${configured?`data-connect-provider="${provider}"`:`data-config-provider="${provider}"`}><span class="entity-mark">${icon(configured?'git':'settings')}</span><span><strong>${configured?label:setupLabel}</strong><small>${configured?t('continueProvider'):setupCopy}</small></span>${configured?badge(t('ready'),'signal'):badge(t('setupRequired'))}${icon('chevron')}</button>`};const reusable=auths.filter(a=>a.status==='active'&&a.webhookStatus==='on_demand').map(a=>`<button class="connection-provider compact" type="button" data-reuse-authorization="${a.id}"><span><strong>${escapeHTML(a.name)}</strong><small>${escapeHTML(a.provider)} · ${t('projectGrants',{count:a.bindingCount})}</small></span>${icon('chevron')}</button>`).join('');const configuredCount=['github','unsupported'].filter(provider=>settings[provider]?.configured).length;openDrawer(t('automaticGitSetup'),`<p class="drawer-note">${t('automaticGitNote')}</p><div class="configuration-meter"><strong>${t('providersReady',{count:configuredCount})}</strong><span>${t('noBackgroundSync')}</span></div><section class="connection-section"><span class="eyebrow">${t('providerConnections')}</span><div class="connection-options">${providerButton('github',t('connectGitHub'))}${providerButton('unsupported',t('connectUnsupportedProvider'))}</div></section>${reusable?`<section class="drawer-section"><span class="eyebrow">${t('reuseVerifiedConnection')}</span><div class="connection-options">${reusable}</div></section>`:''}<section class="drawer-section"><button class="text-action" id="manualUnsupportedProvider" type="button">${t('advancedUnsupportedProviderToken')}</button><p class="inline-note">${t('providerSettingsAdminOnly')}</p></section>`,drawer=>{drawer.querySelectorAll('[data-connect-provider]').forEach(button=>button.onclick=()=>startGitConnection(button.dataset.connectProvider));drawer.querySelectorAll('[data-config-provider]').forEach(button=>button.onclick=()=>providerSettingsForm(button.dataset.configProvider,settings[button.dataset.configProvider]));drawer.querySelectorAll('[data-reuse-authorization]').forEach(button=>button.onclick=()=>reuseAuthorization(button.dataset.reuseAuthorization,auths.find(a=>a.id===button.dataset.reuseAuthorization)));$('#manualUnsupportedProvider').onclick=providerAuthorizationForm})}
function providerSettingsForm(provider,current={}){if(provider==='github')return githubQuickSetup(current);return manualProviderSettingsForm(provider,current)}
async function githubQuickSetup(current={}){const system=await api('/api/system/settings');const returnAddress=system.publicUrl||location.origin;const repositoryOwner=(()=>{try{const parsed=new URL(state.project?.repositoryUrl||'');return parsed.hostname==='github.com'?parsed.pathname.split('/').filter(Boolean)[0]||'':''}catch{return''}})();openDrawer(t('connectGitHubTitle'),`<section class="manifest-intro"><span class="manifest-mark">${icon('git')}</span><div><h3>${t('oneGitHubConfirmation')}</h3><p>${t('githubManifestNote')}</p></div></section><form class="form manifest-form" id="githubManifestForm"><input type="hidden" name="detectedPublicUrl" value="${escapeHTML(returnAddress)}"><div class="provider-callbacks"><strong>${t('returnAddress')}</strong><code>${escapeHTML(returnAddress)}</code></div><details class="manifest-advanced"><summary>${t('createUnderOrganization')}</summary>${field(t('organizationSlug'),'organization','text','',`placeholder="${escapeHTML(repositoryOwner||t('organizationPlaceholder'))}"`)}<p>${t('organizationOptional')}</p></details><div class="permission-summary manifest-permissions"><strong>${t('githubConfirmSettings')}</strong><span>${t('repositoryContentsRW')}</span><span>${t('noWebhookSubscriptions')}</span><span>${t('chooseRepositories')}</span></div><div class="form-error" hidden></div><button class="button primary manifest-submit" type="submit">${icon('git')}${t('continueOnGitHub')}</button><button class="text-action" id="manualGitHub" type="button">${t('advancedManualConfiguration')}</button></form>`,()=>{$('#githubManifestForm').onsubmit=startGitHubManifest;$('#manualGitHub').onclick=()=>manualProviderSettingsForm('github',current)})}
async function manualProviderSettingsForm(provider,current={}){const system=await api('/api/system/settings');if(!system.publicUrl){openDrawer(t('systemAddressRequired'),`<section class="connection-problem"><span class="entity-mark">${icon('settings')}</span><h3>${t('setProjectBoardAddress')}</h3><p>${t('providerReturnOnly')}</p><button class="button primary" id="openSystemSettings" type="button">${t('openSystemSettings')}</button></section>`,()=>{$('#openSystemSettings').onclick=()=>navigate('globalSettings')});return}const github=provider==='github';const providerName=github?'GitHub':'UnsupportedProvider';const secretHint=value=>t(value?'configuredKeepSaved':'requiredFirstSetup');const fields=github?field('GitHub App ID','appId','text',current.appId||'','required')+field(t('githubAppSlug'),'appSlug','text',current.appSlug||'','required')+area(t('githubPrivateKey'),'privateKey','',current.privateKeyConfigured?`placeholder="${t('configuredKeepSaved')}"`:'required placeholder="-----BEGIN PRIVATE KEY-----"'):field(t('unsupportedOAuthID'),'clientId','text',current.clientId||'','required')+field(t('unsupportedBaseURL'),'baseUrl','url',current.baseUrl||'https://unsupported.com','required')+field(`${t('oauthSecret')} · ${secretHint(current.clientSecretConfigured)}`,'clientSecret','password','',current.clientSecretConfigured?'autocomplete="new-password"':'required autocomplete="new-password"');openDrawer(t('advancedProviderConfiguration',{provider:github?'GitHub App':'UnsupportedProvider OAuth'}),`<p class="drawer-note">${t('manualProviderNote')}</p><form class="form provider-settings-form" id="providerSettingsForm">${fields}<div class="provider-callbacks"><strong>${t('providerCallback')}</strong><code>${escapeHTML(system.publicUrl+`/api/git/connections/${provider}/callback`)}</code></div><div class="form-error" hidden></div><button class="button primary" type="submit">${t('saveEnableProvider',{provider:providerName})}</button></form>`,()=>{$('#providerSettingsForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),error=$('.form-error',form);button.disabled=true;error.hidden=true;try{await api(`/api/git/provider-settings/${provider}`,{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(form)))});toast(t('providerConfigurationSaved',{provider:providerName}));await grantForm()}catch(x){error.textContent=x.message;error.hidden=false;button.disabled=false}}})}
async function startGitHubManifest(event){event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),error=$('.form-error',form),popup=window.open('about:blank','projectboard-github-app','popup,width=760,height=780');if(!popup){error.textContent=t('popupBlocked');error.hidden=false;return}button.disabled=true;error.hidden=true;try{const input=Object.fromEntries(new FormData(form));const flow=await api('/api/git/provider-settings/github/manifest/start',{method:'POST',body:JSON.stringify(input)});const post=popup.document.createElement('form');post.method='post';post.action=flow.registrationUrl;const manifest=popup.document.createElement('input');manifest.type='hidden';manifest.name='manifest';manifest.value=flow.manifest;post.append(manifest);popup.document.body.append(post);post.submit();openDrawer(t('creatingGitHubApp'),`<div class="connection-progress"><span class="progress-mark">${icon('git')}</span><h3>${t('confirmOnGitHub')}</h3><p>${t('confirmGitHubAppNote')}</p><button class="button" id="leaveManifestSetup" type="button">${t('cancelSetup')}</button></div>`,()=>{$('#leaveManifestSetup').onclick=async()=>{clearInterval(state.gitPoll);popup.close();try{await api(`/api/git/provider-settings/github/manifest-flows/${flow.id}/cancel`,{method:'POST',body:'{}'})}catch{}grantForm()}});pollGitHubManifest(flow.id,popup)}catch(x){popup.close();error.textContent=x.message;error.hidden=false;button.disabled=false}}
function pollGitHubManifest(id,popup){clearInterval(state.gitPoll);let checking=false;const check=async()=>{if(checking)return;checking=true;try{const flow=await api(`/api/git/provider-settings/github/manifest-flows/${id}`);if(flow.status==='completed'){clearInterval(state.gitPoll);popup?.close();toast(t('githubConfigured'));await grantForm()}else if(flow.status==='failed'){clearInterval(state.gitPoll);popup?.close();renderGitConnectionProblem({provider:'github',status:'failed',errorCode:flow.errorCode,errorMessage:flow.errorMessage})}}catch(error){clearInterval(state.gitPoll);popup?.close();renderGitConnectionProblem({provider:'github',status:'failed',errorCode:'SETUP_STATUS_FAILED',errorMessage:error.message})}finally{checking=false}};check();state.gitPoll=setInterval(check,1200)}
async function startGitConnection(provider){const providerName=provider==='github'?'GitHub':'UnsupportedProvider';const popup=window.open('about:blank','projectboard-git-connect','popup,width=720,height=760');openDrawer(t('connectingProvider',{provider:providerName}),`<div class="connection-progress"><span class="progress-mark">${icon('git')}</span><h3>${t('waitingProvider')}</h3><p>${t('waitingProviderNote')}</p><button class="button" id="cancelGitConnection" type="button">${t('cancelConnection')}</button></div>`);try{const flow=await api(`/api/git/connections/${provider}/start`,{method:'POST',body:JSON.stringify({projectId:state.project.id})});if(popup)popup.location=flow.authorizationUrl;else toast(t('popupBlocked'));$('#cancelGitConnection').onclick=async()=>{await api(`/api/git/connection-flows/${flow.id}/cancel`,{method:'POST',body:'{}'});popup?.close();renderGitConnectionProblem({provider,status:'canceled',errorCode:'AUTHORIZATION_CANCELED',errorMessage:t('connectionCanceled')})};pollGitConnection(flow.id,popup)}catch(error){popup?.close();renderGitConnectionProblem({provider,status:'failed',errorCode:'START_FAILED',errorMessage:error.message})}}
function pollGitConnection(id,popup){clearInterval(state.gitPoll);let checking=false;const check=async()=>{if(checking)return;checking=true;try{const flow=await api(`/api/git/connection-flows/${id}`);if(flow.status==='ready'){clearInterval(state.gitPoll);popup?.close();renderGitConnectionReview(flow)}else if(['failed','canceled','expired'].includes(flow.status)){clearInterval(state.gitPoll);popup?.close();renderGitConnectionProblem(flow)}}catch(error){clearInterval(state.gitPoll);renderGitConnectionProblem({status:'failed',errorCode:'STATUS_FAILED',errorMessage:error.message})}finally{checking=false}};check();state.gitPoll=setInterval(check,1200)}
function renderGitConnectionReview(flow){const selected=flow.matchedRepositoryId||flow.repositories[0]?.id||'';const options=flow.repositories.map(repo=>`<option value="${repo.id}" ${repo.id===selected?'selected':''}>${escapeHTML(repo.name)}${repo.canWrite?'':` · ${t('readOnly')}`}</option>`).join('');const attention=flow.errorCode==='NO_MATCHING_REPOSITORY'?`<p class="connection-warning">${t('noMatchingRepository')}</p>`:'';openDrawer(t('reviewGitAccess'),`<section class="connection-review"><div class="review-status">${badge(t('providerConnected'),'signal')}${badge(t('onDemandCommitSync'),'signal')}</div><h3>${t('confirmProjectBinding')}</h3><p>${t('nothingBoundYet')}</p>${attention}<form class="form" id="gitConnectionForm"><label class="field"><span>${t('repository')}</span><select name="repositoryId" required>${options}</select></label><label class="field"><span>${t('accessLevel')}</span><select name="accessLevel"><option value="write">${t('write')}</option><option value="read">${t('read')}</option></select></label><div class="permission-summary"><strong>${t('effectiveBoundary')}</strong><span>${t('oneProjectBoundary')}</span><span>${t('syncOnlyOnRequest')}</span></div><div class="form-error" hidden></div><button class="button primary" type="submit">${t('createRepositoryGrant')}</button></form></section>`,()=>wireForm('#gitConnectionForm',d=>api(`/api/git/connection-flows/${flow.id}/complete`,{method:'POST',body:JSON.stringify(d)})))}
function renderGitConnectionProblem(flow){const errorMessages={AUTHORIZATION_CANCELED:t('authorizationCanceled'),CALLBACK_EXPIRED:t('callbackExpired'),NO_ACCESSIBLE_REPOSITORIES:t('noAccessibleRepositories'),INSUFFICIENT_PROVIDER_PERMISSION:t('insufficientPermission')};openDrawer(t('gitSetupAttention'),`<section class="connection-problem"><span class="entity-mark">${icon('x')}</span><h3>${escapeHTML(flow.errorCode||'CONNECTION_FAILED')}</h3><p>${escapeHTML(errorMessages[flow.errorCode]||flow.errorMessage||t('connectionFailed'))}</p><div class="drawer-actions"><button class="button primary" id="retryGitConnection" type="button">${t('tryAgain')}</button><button class="button" id="closeGitProblem" type="button">${t('close')}</button></div></section>`,()=>{$('#retryGitConnection').onclick=grantForm;$('#closeGitProblem').onclick=closeDrawer})}
async function reuseAuthorization(id,authorization){const repositories=await api(`/api/provider-authorizations/${id}/repositories`);if(!repositories.length){renderGitConnectionProblem({errorCode:'NO_ACCESSIBLE_REPOSITORIES'});return}const matched=repositories.find(repo=>normalizedRepositoryURL(repo.cloneUrl)===normalizedRepositoryURL(state.project.repositoryUrl));const options=repositories.map(repo=>`<option value="${repo.id}" ${repo===matched?'selected':''}>${escapeHTML(repo.name)}${repo.canWrite?'':` · ${t('readOnly')}`}</option>`).join('');openDrawer(t('reuseConnection'),formShell(`<input type="hidden" name="authorizationId" value="${id}"><label class="field"><span>${t('connection')}</span><input value="${escapeHTML(authorization.name)}" disabled></label><label class="field"><span>${t('repository')}</span><select name="repositoryId" id="reusedRepository" required>${options}</select></label><label class="field"><span>${t('accessLevel')}</span><select name="accessLevel"><option value="write">${t('write')}</option><option value="read">${t('read')}</option></select></label>`,t('separateGrantNote')),()=>wireForm('#drawerForm',d=>{const repo=repositories.find(item=>item.id===d.repositoryId);return api(`/api/projects/${state.project.id}/repository-grant`,{method:'POST',body:JSON.stringify({...d,repositoryName:repo.name,cloneUrl:repo.cloneUrl,defaultBranch:repo.defaultBranch})})}))}
function normalizedRepositoryURL(value=''){return value.toLowerCase().replace(/^git@/,'').replace(':','/').replace(/^https?:\/\//,'').replace(/^ssh:\/\//,'').replace(/\.git$/,'').replace(/\/$/,'')}
function providerAuthorizationForm(){const fields=field(t('connectionName'),'name','text',t('unsupportedAccessToken'),'required')+field(t('unsupportedBaseURL'),'baseUrl','url','https://unsupported.com','required')+area(t('personalAccessToken'),'secret','','required')+field(t('repositoryID'),'repositoryId','text','','required')+field(t('repositoryName'),'repositoryName','text','','required')+field(t('cloneURL'),'cloneUrl','url',state.project.repositoryUrl,'required')+field(t('defaultBranch'),'defaultBranch','text',state.project.defaultTargetBranch,'required')+`<label class="field"><span>${t('accessLevel')}</span><select name="accessLevel"><option value="write">${t('write')}</option><option value="read">${t('read')}</option></select></label><input type="hidden" name="provider" value="unsupported">`;openDrawer(t('advancedUnsupportedProviderSetup'),formShell(fields,t('manualTokenNote')),()=>wireForm('#drawerForm',async d=>{const grant={repositoryId:d.repositoryId,repositoryName:d.repositoryName,cloneUrl:d.cloneUrl,defaultBranch:d.defaultBranch,accessLevel:d.accessLevel};delete d.repositoryId;delete d.repositoryName;delete d.cloneUrl;delete d.defaultBranch;delete d.accessLevel;const authorization=await api('/api/provider-authorizations',{method:'POST',body:JSON.stringify(d)});return api(`/api/projects/${state.project.id}/repository-grant`,{method:'POST',body:JSON.stringify({...grant,authorizationId:authorization.id})})}))}
async function renderUsers(){const data=await api('/api/users');const actions=`<button class="button primary" id="newUser">${icon('plus')}${t('createUser')}</button>`;const rows=data.map(x=>`<button class="table-row action user-row" data-user="${x.id}" aria-label="${t('openUserSettings',{name:escapeHTML(x.displayName)})}"><span class="user-identity"><span class="user-avatar">${escapeHTML(x.displayName.trim().slice(0,1).toUpperCase()||'?')}</span><span><strong>${escapeHTML(x.displayName)}</strong><small>@${escapeHTML(x.username)}</small></span></span><span>${t(x.systemRole)}</span><span>${t('projectsCount',{count:x.membershipCount})}</span><span class="user-status">${badge(t(x.status),x.status==='disabled'?'danger':'')}${icon('chevron')}</span></button>`).join('');$('#workspace').innerHTML=header(t('users'),t('usersDescription'),actions)+`<div class="content"><div class="table">${rows}</div></div>`;$('#newUser').onclick=userForm;document.querySelectorAll('[data-user]').forEach(row=>row.onclick=()=>userSettings(row.dataset.user))}
async function userSettings(id){openDrawer(t('userSettings'),`<div class="drawer-loading">${t('loadingAccount')}</div>`);try{const user=await api(`/api/users/${id}`);renderUserSettings(user)}catch(error){const loading=$('#drawer .drawer-loading');if(loading)loading.outerHTML=`<div class="form-error">${escapeHTML(error.message)}</div>`}}
function renderUserSettings(user){const drawer=$('#drawer');if(!drawer)return;const isSelf=user.id===state.me.id;const memberships=(user.memberships||[]).map(m=>`<div><dt>${escapeHTML(m.name)}</dt><dd>${badge(t(m.role),m.role==='developer'?'signal':'')}</dd></div>`).join('')||`<p class="empty-note">${t('noProjectMemberships')}</p>`;drawer.innerHTML=`<header class="drawer-head"><div><span class="eyebrow">${t('userAccount')} / @${escapeHTML(user.username)}</span><h2>${escapeHTML(user.displayName)}</h2></div><button class="icon-button" id="closeDrawer" aria-label="${t('close')}">${icon('x')}</button></header><section class="user-summary"><div class="user-avatar large">${escapeHTML(user.displayName.trim().slice(0,1).toUpperCase()||'?')}</div><div><div class="user-summary-badges">${badge(t(user.status),user.status==='disabled'?'danger':'')}${isSelf?badge(t('currentAccount'),'signal'):''}</div><p>${t(user.status==='disabled'?'disabledUserNote':'activeUserNote')}</p></div></section><form class="form user-settings-form" id="userSettingsForm">${field(t('displayName'),'displayName','text',user.displayName,'required')}<label class="field"><span>${t('username')}</span><input value="@${escapeHTML(user.username)}" disabled></label><label class="field"><span>${t('systemRole')}</span><select name="systemRole"><option value="user" ${user.systemRole==='user'?'selected':''}>${t('user')}</option><option value="administrator" ${user.systemRole==='administrator'?'selected':''}>${t('administrator')}</option></select></label><div class="form-error" hidden></div><button class="button primary" type="submit">${t('save')}</button></form><section class="drawer-section"><span class="eyebrow">${t('projectAccess')} / ${(user.memberships||[]).length}</span><div class="kv user-memberships">${memberships}</div></section><section class="drawer-section security-section"><span class="eyebrow">${t('accountSecurity')}</span><p>${t('passwordSecurityNote')}</p><div class="drawer-actions"><button class="button" id="resetUserPassword" type="button">${icon('shield')}${t('resetPassword')}</button>${user.status==='disabled'?`<button class="button primary" id="toggleUserStatus" type="button">${t('enableUser')}</button>`:`<button class="button danger" id="toggleUserStatus" type="button" ${isSelf?`disabled title="${t('cannotDisableSelf')}"`:''}>${t('disableUser')}</button>`}</div>${isSelf?`<p class="inline-note">${t('cannotDisableSelf')}</p>`:''}</section>`;$('#closeDrawer').onclick=closeDrawer;$('#userSettingsForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),error=$('.form-error',form);button.disabled=true;error.hidden=true;try{await api(`/api/users/${user.id}`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(form)))});toast(t('userSettingsSaved'));await renderUsers();await userSettings(user.id)}catch(x){error.textContent=x.message;error.hidden=false}finally{button.disabled=false}};$('#resetUserPassword').onclick=()=>resetUserPassword(user);const toggle=$('#toggleUserStatus');if(toggle)toggle.onclick=()=>user.status==='disabled'?enableUser(user):disableUser(user)}
async function resetUserPassword(user){const button=$('#resetUserPassword');button.disabled=true;try{const result=await api(`/api/users/${user.id}/reset-password`,{method:'POST',body:'{}'});openDrawer(t('temporaryPassword'),`<p class="drawer-note">${t('temporaryPasswordNote',{name:escapeHTML(user.displayName)})}</p><div class="secret-reveal"><code id="temporaryPassword">${escapeHTML(result.temporaryPassword)}</code><button class="button" id="copyTemporaryPassword" type="button">${t('copy')}</button></div>`,()=>{$('#copyTemporaryPassword').onclick=async()=>{await navigator.clipboard.writeText(result.temporaryPassword);toast(t('temporaryPasswordCopied'))}})}catch(error){toast(error.message);button.disabled=false}}
function disableUser(user){openDrawer(t('disableUser'),formShell(area(t('reason'),'reason','','required'),t('disableUserNote')),()=>wireForm('#drawerForm',d=>api(`/api/users/${user.id}/disable`,{method:'POST',body:JSON.stringify(d)})))}
async function enableUser(user){const button=$('#toggleUserStatus');button.disabled=true;try{await api(`/api/users/${user.id}/enable`,{method:'POST',body:'{}'});toast(t('userEnabled'));await renderUsers();await userSettings(user.id)}catch(error){toast(error.message);button.disabled=false}}
function userForm(){const fields=field(t('displayName'),'displayName','text','','required')+field(t('username'),'username','text','','required pattern="[a-z0-9._-]{2,64}"')+`<label class="field"><span>${t('systemRole')}</span><select name="systemRole"><option value="user">${t('user')}</option><option value="administrator">${t('administrator')}</option></select></label>`;openDrawer(t('createUser'),formShell(fields,t('generatedPasswordNote')),()=>wireForm('#drawerForm',async d=>{const result=await api('/api/users',{method:'POST',body:JSON.stringify(d)});toast(`${t('temporaryPassword')}: ${result.temporaryPassword}`)}))}
async function renderProjects(){const actions=`<button class="button primary" id="newProject">${icon('plus')}${t('createProject')}</button>`;const rows=state.projects.map(p=>`<button class="table-row action management-row" data-managed-project="${p.id}"><span><strong>${escapeHTML(p.name)}</strong><small>${escapeHTML(p.key)}</small></span><span class="row-end">${badge(t(p.archivedAt?'archived':'active'),p.archivedAt?'':'signal')}${icon('chevron')}</span></button>`).join('');$('#workspace').innerHTML=header(t('projects'),t('projectsBasicDescription'),actions)+`<div class="content"><div class="table projects-basic-list">${rows||emptyState(t('noProjects'),t('noProjectsNote'))}</div></div>`;$('#newProject').onclick=projectForm;document.querySelectorAll('[data-managed-project]').forEach(row=>row.onclick=()=>projectSettings(state.projects.find(p=>p.id===row.dataset.managedProject)))}
function editManagedProjectIdentity(project){openDrawer(t('editProject'),formShell(field(t('name'),'name','text',project.name,'required')),()=>wireForm('#drawerForm',async data=>{await api(`/api/projects/${project.id}`,{method:'PATCH',body:JSON.stringify({name:data.name})});await loadProjects();renderProjects()}))}
function projectSettings(project){const isCurrent=project.id===state.project?.id;openDrawer(t('projectSettings'),`<section class="entity-summary"><span class="project-mark large">${escapeHTML(project.key.slice(0,2).toUpperCase())}</span><div><span class="eyebrow">${t('projectLabel')} / ${escapeHTML(project.key)}</span><h3>${escapeHTML(project.name)}</h3><div>${badge(t(project.archivedAt?'archived':'active'),project.archivedAt?'':'signal')} ${isCurrent?badge(t('current'),'signal'):''}</div></div></section><div class="drawer-actions"><button class="button primary" id="openProject" type="button">${t(isCurrent?'openTaskQueue':'switchToProject')}</button><button class="button" id="editManagedProject" type="button">${icon('settings')}${t('editProject')}</button></div>`,()=>{$('#openProject').onclick=()=>{state.project=project;localStorage.pbProject=project.id;state.page='queue';closeDrawer();renderShell()};$('#editManagedProject').onclick=()=>editManagedProjectIdentity(project)})}
async function renderActivity(){const data=state.project?await api(`/api/activity?projectId=${state.project.id}`):[];const rows=data.map((e,index)=>`<button class="table-row action management-row" data-event="${index}"><span><strong>${escapeHTML(e.event_type)}</strong><small>${escapeHTML(e.created_at)}</small></span><span>${escapeHTML(e.actor_type)}</span><span>${escapeHTML(e.object_type)}</span><span class="row-end">${escapeHTML(e.object_id)}${icon('chevron')}</span></button>`).join('');$('#workspace').innerHTML=header(t('activity'),t('activityDescription'))+`<div class="content"><div class="table">${rows||`<p>${t('noActivity')}</p>`}</div></div>`;document.querySelectorAll('[data-event]').forEach(row=>row.onclick=()=>activityDetails(data[Number(row.dataset.event)]))}
function activityDetails(event){let payload={};try{payload=JSON.parse(event.payload_json||'{}')}catch{payload={raw:event.payload_json}}const entries=Object.entries(payload).map(([key,value])=>`<div><dt>${escapeHTML(key)}</dt><dd>${escapeHTML(typeof value==='object'?JSON.stringify(value):value)}</dd></div>`).join()||`<p class="empty-note">${t('noPayload')}</p>`;openDrawer(t('activityDetails'),`<section class="entity-summary"><span class="entity-mark">${icon('activity')}</span><div><span class="eyebrow">${t('auditEvent')}</span><h3>${escapeHTML(event.event_type)}</h3><div>${badge(event.source||'web')} ${badge(event.actor_type)}</div></div></section><section class="drawer-section"><div class="kv"><div><dt>${t('occurred')}</dt><dd>${escapeHTML(event.created_at)}</dd></div><div><dt>${t('actorID')}</dt><dd>${escapeHTML(event.actor_id||'—')}</dd></div><div><dt>${t('object')}</dt><dd>${escapeHTML(`${event.object_type} / ${event.object_id}`)}</dd></div><div><dt>${t('eventID')}</dt><dd>${escapeHTML(event.id)}</dd></div></div></section><section class="drawer-section"><span class="eyebrow">${t('recordedPayload')}</span><div class="kv payload-kv">${entries}</div></section>`)}
function passwordForm(){openDrawer(t('changePassword'),formShell(field(t('currentPassword'),'currentPassword','password','','required')+field(t('newPassword'),'newPassword','password','','required minlength="12"')),()=>wireForm('#drawerForm',d=>api('/api/me/change-password',{method:'POST',body:JSON.stringify(d)})))}
renderSystemSettings=async function(){
  const settings=await api('/api/system/settings');
  const value=settings.publicUrl||location.origin;
  $('#workspace').innerHTML=header(t('globalSettings'),'')+`<div class="content simple-settings-page">
    <section class="settings-sheet">
      <header class="settings-sheet-head"><h2>${t('systemAddress')}</h2><span class="setting-state">${t(settings.publicUrl?'configured':'notSaved')}</span></header>
      <form class="simple-setting-form" id="systemSettingsForm">${field(t('projectBoardURL'),'publicUrl','url',value,'required')}<div class="form-error" hidden></div><button class="button primary" type="submit">${t('save')}</button></form>
    </section>
  </div>`;
  $('#systemSettingsForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),error=$('.form-error',form);button.disabled=true;error.hidden=true;try{await api('/api/system/settings',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(form)))});toast(t('systemSettingsSaved'));renderSystemSettings()}catch(x){error.textContent=x.message;error.hidden=false;button.disabled=false}};
};

renderSettings=async function(){
  if(!state.project)return renderQueue();
  let grant=null;try{grant=await api(`/api/projects/${state.project.id}/repository-grant`)}catch{}
  const actions=`<button class="button" id="editProject">${t('editProject')}</button>${grant?`<button class="button" id="syncCommits">${icon('activity')}${t('syncRecentCommits')}</button>`:''}<button class="button primary" id="gitGrant">${icon('git')}${t(grant?'changeGitAccess':'automaticGitSetup')}</button>`;
  const grantDetails=grant?`<dl class="simple-setting-rows"><div><dt>${t('status')}</dt><dd><span class="setting-state blue">${t('connected')}</span></dd></div><div><dt>${t('repository')}</dt><dd>${escapeHTML(grant.repositoryName)}</dd></div><div><dt>${t('provider')}</dt><dd>${escapeHTML(grant.provider)}</dd></div><div><dt>${t('accessLevel')}</dt><dd>${t(grant.accessLevel)}</dd></div><div><dt>${t('syncMode')}</dt><dd>${t('onDemand')}</dd></div></dl>`:`<div class="simple-empty-setting"><span class="setting-state">${t('notConnected')}</span><strong>${t('noRepositoryGrant')}</strong></div>`;
  $('#workspace').innerHTML=header(t('settings'),escapeHTML(state.project.name),actions)+`<div class="content simple-settings-page project-simple-settings">
    <section class="settings-sheet">
      <header class="settings-sheet-head"><h2>${t('gitRepository')}</h2></header>${grantDetails}
    </section>
    <section class="settings-sheet">
      <header class="settings-sheet-head"><h2>${t('repositoryAndBranches')}</h2><span class="setting-state">${t('version',{version:state.project.configVersion})}</span></header>
      <dl class="simple-setting-rows"><div><dt>${t('repositoryURL')}</dt><dd>${escapeHTML(state.project.repositoryUrl)}</dd></div><div><dt>${t('defaultBranch')}</dt><dd>${escapeHTML(state.project.defaultTargetBranch)}</dd></div><div><dt>${t('allowedBranches')}</dt><dd>${escapeHTML((state.project.allowedTargetBranches||[]).join(', ')||t('notSet'))}</dd></div></dl>
    </section>
  </div>`;
  $('#editProject').onclick=()=>editProjectForm(state.project);$('#gitGrant').onclick=grantForm;const sync=$('#syncCommits');if(sync)sync.onclick=async()=>{sync.disabled=true;try{const result=await api(`/api/projects/${state.project.id}/sync-commits`,{method:'POST',body:'{}'});toast(t('syncResult',{fetched:result.fetched,inserted:result.inserted}))}catch(error){toast(error.message)}finally{sync.disabled=false}};
};

function taskModeLabel(mode){
  if(mode==='manual')return state.locale==='zh'?'人工':'Manual';
  if(mode==='human')return t('human');
  if(mode==='agent')return t('agent');
  return mode||t('notSet');
}

function taskDate(value){
  if(!value)return t('notSet');
  const date=new Date(value);
  if(Number.isNaN(date.valueOf()))return value;
  return new Intl.DateTimeFormat(state.locale==='zh'?'zh-CN':'en',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(date);
}

async function loadTaskActors(){
  if(!state.project)return [];
  try{
    const [members,agents]=await Promise.all([api(`/api/projects/${state.project.id}/members`),api(`/api/projects/${state.project.id}/agents`)]);
    return [
      ...members.filter(member=>member.role).map(member=>({id:member.id,kind:'human',name:member.displayName,available:member.status==='active'})),
      ...agents.map(agent=>({id:agent.id,kind:'agent',name:agent.name,available:agent.status==='active'&&agent.enabled}))
    ];
  }catch{return []}
}

function taskAssignee(item,actors){
  return actors.find(actor=>actor.kind===item.assignee_kind&&actor.id===item.assignee_id)||{id:item.assignee_id||'',kind:item.assignee_kind||'',name:item.assignee_kind?t(item.assignee_kind):t('unassigned'),available:false};
}

function taskAvatar(name,fallback='?'){
  return escapeHTML((name||fallback).trim().slice(0,1).toUpperCase()||fallback);
}

function taskRowMarkup(item,actors,options={}){
  const assignee=taskAssignee(item,actors);
  const row=`<${options.parent?'div':'button'} class="work-item work-row ${state.queuePreview===item.id?'selected':''}" data-id="${item.id}" ${options.parent?'role="button" tabindex="0"':''}>
    <i class="priority-bar ${item.priority}"></i>
    <span class="work-main">
      <span class="work-line">${options.parent?`<button class="parent-toggle ${options.open?'open':''}" type="button" data-toggle-parent="${item.id}" aria-label="${t(options.open?'collapseChildren':'expandChildren')}">${icon('chevron')}</button>`:''}<span class="work-id">${escapeHTML(item.id)}</span>${options.parent?badge(t('parentItem',{completed:options.completed,total:options.total})):badge(t(item.stage),item.stage==='execution'||item.stage==='acceptance'?'signal':'')}${item.blocked_at?badge(t('blocked'),'danger'):''}</span>
      <strong class="work-item-title">${escapeHTML(item.title)}</strong>
      <span class="work-meta">${options.parent?`<span>${t(item.stage)}</span><i>·</i><span>${t('blockedChildren',{count:options.blocked})}</span>`:`<span>${t('discussionMode')} ${taskModeLabel(item.discussion_mode)}</span><i>·</i><span>${t('executionMode')} ${taskModeLabel(item.execution_mode)}</span>`}<i>·</i><span>${escapeHTML(item.target_branch)}</span><i>·</i><span>${taskDate(item.updated_at)}</span></span>
    </span>
    <span class="work-side"><span class="task-avatar" title="${escapeHTML(assignee.name)}">${taskAvatar(assignee.name,item.assignee_kind==='agent'?'A':'H')}</span>${badge(t(item.priority))}</span>
  </${options.parent?'div':'button'}>`;
  if(!options.parent)return row;
  return `<div class="parent-item">${row}<div class="child-list" ${options.open?'':'hidden'}>${options.children.map(child=>taskRowMarkup(child,actors,{child:true})).join('')}</div></div>`;
}

renderQueue=async function(){
  if(!state.project){$('#workspace').innerHTML=header(t('queue'),t('noProjectsNote'),`<button class="button primary" id="createProject">${icon('plus')}${t('createProject')}</button>`)+emptyState(t('noProjects'),t('noProjectsNote'));$('#createProject').onclick=projectForm;return}
  const [items,actors]=await Promise.all([api(`/api/work-items?projectId=${encodeURIComponent(state.project.id)}`),loadTaskActors()]);
  state.items=items;
  if(state.task){await renderTask();return}
  state.queueStage=state.queueStage||'all';state.queueMine=Boolean(state.queueMine);state.queueQuery=state.queueQuery||'';state.queuePriority=state.queuePriority||'all';state.queueBlocker=state.queueBlocker||'any';state.expandedParents=state.expandedParents||new Set();
  const stageTabs=[['all','queueAll'],['todo','todo'],['discussion','discussion'],['execution','execution'],['acceptance','acceptance'],['completed','completed'],['abandoned','abandoned']];
  const filterActive=state.queuePriority!=='all'||state.queueBlocker!=='any';
  $('#workspace').innerHTML=`<header class="queue-page-head">
    <div class="queue-title"><div><h1>${t('queue')}</h1><p>${escapeHTML(state.project.name)} · ${escapeHTML(state.project.repositoryUrl)}</p></div><button class="button primary" id="newItem">${icon('plus')}${t('createItem')}</button></div>
    <div class="queue-tabs" role="tablist" aria-label="${t('queueView')}">${stageTabs.map(([stage,label])=>`<button class="queue-tab ${state.queueStage===stage?'active':''}" data-queue-stage="${stage}" role="tab" aria-selected="${state.queueStage===stage}">${t(label)} <span>${stage==='all'?items.length:items.filter(item=>item.stage===stage).length}</span></button>`).join('')}</div>
    <div class="queue-tools"><label class="search">${icon('search')}<input id="queueSearch" value="${escapeHTML(state.queueQuery)}" placeholder="${t('search')}"></label><button class="button ${state.queueMine?'active':''}" id="mineToggle" aria-pressed="${state.queueMine}">${t('queueMine')}</button><button class="button ${filterActive?'active':''}" id="queueFilter">${icon('filter')}${t(filterActive?'filterActive':'filter')}</button><span class="queue-count">${t('itemsCount',{count:items.length})}</span></div>
  </header><div class="queue-content" id="queueList"></div>`;
  const paint=()=>{
    const query=state.queueQuery.trim().toLowerCase();
    const matches=item=>(state.queueStage==='all'||item.stage===state.queueStage)&&(!state.queueMine||(item.assignee_kind==='human'&&item.assignee_id===state.me.id))&&(state.queuePriority==='all'||item.priority===state.queuePriority)&&(state.queueBlocker==='any'||(state.queueBlocker==='blocked')===Boolean(item.blocked_at))&&(!query||`${item.id} ${item.title}`.toLowerCase().includes(query));
    const childrenByParent=new Map();items.forEach(item=>{if(item.parent_id){const children=childrenByParent.get(item.parent_id)||[];children.push(item);childrenByParent.set(item.parent_id,children)}});
    const roots=items.filter(item=>!item.parent_id||!items.some(candidate=>candidate.id===item.parent_id));
    const visibleRoots=roots.map(item=>({item,children:(childrenByParent.get(item.id)||[]).filter(matches)})).filter(entry=>matches(entry.item)||entry.children.length);
    const groupFor=entry=>entry.children.length||childrenByParent.has(entry.item.id)?'parentWork':entry.item.blocked_at?'needsAttention':!entry.item.assignee_id?'unassignedWork':entry.item.stage==='completed'?'completedWork':entry.item.stage==='abandoned'?'abandonedWork':'activeWork';
    const order=['needsAttention','activeWork','unassignedWork','parentWork','completedWork','abandonedWork'];
    const groups=order.map(label=>[label,visibleRoots.filter(entry=>groupFor(entry)===label)]).filter(([,group])=>group.length);
    $('#queueList').innerHTML=groups.length?groups.map(([label,group])=>`<section class="queue-group"><div class="group-label">${t(label)} <span>${group.length}</span></div>${group.map(entry=>{const allChildren=childrenByParent.get(entry.item.id)||[];return taskRowMarkup(entry.item,actors,allChildren.length?{parent:true,children:entry.children,open:state.expandedParents.has(entry.item.id),completed:allChildren.filter(child=>child.stage==='completed').length,total:allChildren.length,blocked:allChildren.filter(child=>child.blocked_at).length}:{})}).join('')}</section>`).join(''):`<section class="queue-empty"><strong>${t('noMatchingItems')}</strong><p>${t('noMatchingItemsNote')}</p></section>`;
    document.querySelectorAll('.work-row[data-id]').forEach(row=>{row.onclick=()=>{const item=items.find(candidate=>candidate.id===row.dataset.id);state.queuePreview=item.id;document.querySelectorAll('.work-row.selected').forEach(selected=>selected.classList.remove('selected'));row.classList.add('selected');taskPreview(item,actors)};if(row.getAttribute('role')==='button')row.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();row.click()}}});
    document.querySelectorAll('[data-toggle-parent]').forEach(button=>button.onclick=event=>{event.stopPropagation();const id=button.dataset.toggleParent;state.expandedParents.has(id)?state.expandedParents.delete(id):state.expandedParents.add(id);paint()});
  };
  paint();
  $('#newItem').onclick=workItemForm;
  $('#queueSearch').oninput=event=>{state.queueQuery=event.target.value;paint()};
  $('#mineToggle').onclick=()=>{state.queueMine=!state.queueMine;renderQueue()};
  $('#queueFilter').onclick=queueFilterForm;
  document.querySelectorAll('[data-queue-stage]').forEach(button=>button.onclick=()=>{state.queueStage=button.dataset.queueStage;renderQueue()});
};

function queueFilterForm(){
  openDrawer(t('filterWorkItems'),`<form class="form" id="queueFilterForm"><label class="field"><span>${t('priority')}</span><select name="priority"><option value="all">${t('allPriorities')}</option>${['urgent','high','medium','low'].map(value=>`<option value="${value}" ${state.queuePriority===value?'selected':''}>${t(value)}</option>`).join('')}</select></label><label class="field"><span>${t('blockerFilter')}</span><select name="blocker"><option value="any">${t('anyBlocker')}</option><option value="blocked" ${state.queueBlocker==='blocked'?'selected':''}>${t('blockedOnly')}</option><option value="unblocked" ${state.queueBlocker==='unblocked'?'selected':''}>${t('unblockedOnly')}</option></select></label><button class="button primary" type="submit">${t('applyFilters')}</button></form>`,()=>{$('#queueFilterForm').onsubmit=event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget));state.queuePriority=data.priority;state.queueBlocker=data.blocker;closeDrawer();renderQueue()}});
}

function taskPreview(item,actors){
  const assignee=taskAssignee(item,actors),terminal=['completed','abandoned'].includes(item.stage),criteria=(item.acceptance_criteria_markdown||'').split(/\r?\n/).filter(Boolean);
  openDrawer(t('taskDetails'),`<section class="task-preview"><div class="task-preview-id">${escapeHTML(item.id)} · ${t('version',{version:item.version})}</div><h3>${escapeHTML(item.title)}</h3><div class="task-preview-badges">${badge(t(item.stage),item.stage==='execution'||item.stage==='acceptance'?'signal':'')}${item.blocked_at?badge(t('blocked'),'danger'):''}${badge(t(item.priority))}</div><p class="task-preview-description">${escapeHTML(item.description_markdown||t('noDescription'))}</p><div class="task-preview-actions"><button class="button primary" id="openFullTask">${t('openFullItem')}</button><button class="button" id="previewMessage">${t('sendMessage')}</button>${terminal?'':`<button class="button" id="previewAssign">${t('changeExecutor')}</button>`}</div><dl class="task-preview-kv"><div><dt>${t('currentStage')}</dt><dd>${t(item.stage)}</dd></div><div><dt>${t('executor')}</dt><dd>${escapeHTML(assignee.name)}</dd></div><div><dt>${t('discussionMode')}</dt><dd>${taskModeLabel(item.discussion_mode)}</dd></div><div><dt>${t('executionMode')}</dt><dd>${taskModeLabel(item.execution_mode)}</dd></div><div><dt>${t('acceptanceMode')}</dt><dd>${taskModeLabel(item.acceptance_mode)}</dd></div><div><dt>${t('targetBranch')}</dt><dd><code>${escapeHTML(item.target_branch)}</code></dd></div></dl>${item.blocked_at?`<section class="task-preview-section"><h4>${t('blocker')}</h4><div class="task-preview-blocker"><strong>${taskDate(item.blocked_at)}</strong><p>${escapeHTML(item.blocked_reason||t('blocked'))}</p></div></section>`:''}<section class="task-preview-section"><h4>${t('acceptanceStandards')}</h4>${criteria.length?criteria.map(criterion=>`<div class="preview-criterion"><i></i><span>${escapeHTML(criterion)}</span></div>`).join(''):`<p>${t('noCriteria')}</p>`}</section></section>`,()=>{$('#openFullTask').onclick=()=>{state.task=item.id;closeDrawer();renderQueue()};$('#previewMessage').onclick=()=>messageForm(item);const assign=$('#previewAssign');if(assign)assign.onclick=()=>taskAssignmentForm(item,actors)});
}

function taskEventText(event){
  const payload=event.payload||(()=>{try{return JSON.parse(event.payload_json||'{}')}catch{return {}}})();
  const value=payload.markdown||payload.noteMarkdown||payload.reason||payload.summaryMarkdown||payload.goalMarkdown||payload.message;
  return value||JSON.stringify(payload,null,2);
}

function taskEventAuthor(event,actors){
  if(event.author_type==='system'||!event.author_type)return t('systemAuthor');
  return actors.find(actor=>actor.kind===event.author_type&&actor.id===event.author_id)?.name||event.author_type;
}

function taskEventMarkup(event,actors){
  const author=taskEventAuthor(event,actors);
  return `<article class="conversation-entry"><span class="entry-avatar">${taskAvatar(author,'·')}</span><div class="entry-content"><div class="entry-head"><strong>${escapeHTML(author)}</strong><time>${taskDate(event.created_at)}</time>${event.stage?badge(t(event.stage)):''}</div><div class="entry-body">${escapeHTML(taskEventText(event))}</div></div></article>`;
}

function phaseMarkup(item){
  const current=stages.indexOf(item.stage);
  return stages.map((stage,index)=>{
    const done=index<current||item.stage==='completed';
    const active=index===current&&item.stage!=='completed';
    const stateText=done?t('phaseDone'):active?t('phaseCurrent'):t('phaseWaiting');
    return `<div class="phase-band-step ${done?'done':active?'active':''}" role="listitem" ${active?'aria-current="step"':''}><span class="phase-node-mark">${done?icon('check'):index+1}</span><span class="phase-node-copy"><strong>${t(stage)}</strong><small>${stateText}</small></span></div>`;
  }).join('');
}

renderTask=async function(){
  const [item,actors]=await Promise.all([api(`/api/work-items/${state.task}`),loadTaskActors()]);
  const assignee=taskAssignee(item,actors),current=Math.max(1,stages.indexOf(item.stage)+1),terminal=['completed','abandoned'].includes(item.stage);
  const progress=item.stage==='completed'?t('routeComplete'):item.stage==='abandoned'?t('abandoned'):item.blocked_at?t('routeBlocked',{current}):t('routeCurrent',{current,stage:t(item.stage)});
  const badges=`${badge(t(item.stage),item.stage==='execution'||item.stage==='acceptance'?'signal':'')}${item.blocked_at?badge(t('blocked'),'danger'):''}${badge(t(item.priority))}`;
  $('#workspace').innerHTML=`<header class="task-page-header">
    <button class="back-link" id="back">${icon('chevron')}${t('queue')}</button>
    <div class="task-heading"><div class="task-heading-main"><div class="task-heading-id">${escapeHTML(item.id)} · ${t('version',{version:item.version})}</div><h1>${escapeHTML(item.title)}</h1><div class="task-heading-badges">${badges}</div></div><div class="task-heading-actions"><button class="button" id="message">${t('sendMessage')}</button>${terminal?'':`<button class="button" id="changeAssignee">${t('changeExecutor')}</button><button class="button danger" id="abandonItem">${t('abandonItem')}</button><button class="button primary" id="primaryTaskAction">${t(item.stage==='todo'?'changeExecutor':'stageNext')}</button>`}</div></div>
    <div class="task-meta-strip"><div class="task-meta-item"><span>${t('project')}</span><strong>${escapeHTML(state.project.name)}</strong></div><div class="task-meta-item"><span>${t('executor')}</span><strong>${escapeHTML(assignee.name)}</strong></div><div class="task-meta-item"><span>${t('discussionMode')}</span><strong>${taskModeLabel(item.discussion_mode)}</strong></div><div class="task-meta-item"><span>${t('executionMode')}</span><strong>${taskModeLabel(item.execution_mode)}</strong></div><div class="task-meta-item"><span>${t('acceptanceMode')}</span><strong>${taskModeLabel(item.acceptance_mode)}</strong></div><div class="task-meta-item"><span>${t('updated')}</span><strong>${taskDate(item.updated_at)}</strong></div></div>
    <div class="phase-overview"><div class="phase-overview-head"><span>${t('routeProgress')}</span><strong>${progress}</strong></div><div class="phase-scroll"><div class="phase-band" role="list">${phaseMarkup(item)}</div></div></div>
  </header><div class="task-page-body"><section class="conversation-stream"><div class="conversation-intro"><div><h2>${t('taskDescription')}</h2><p>${escapeHTML(item.description_markdown||t('noDescription'))}</p></div><div><h2>${t('acceptanceCriteria')}</h2><p>${escapeHTML(item.acceptance_criteria_markdown||t('noCriteria'))}</p></div></div><div class="conversation-timeline">${(item.conversation||[]).map(event=>taskEventMarkup(event,actors)).join('')||`<p class="conversation-empty">${t('noEvents')}</p>`}</div><div class="conversation-compose"><p>${t('timelineNote')}</p><button class="button primary" id="continueConversation">${t('continueConversation')}</button></div></section></div>`;
  $('#back').onclick=()=>{state.task=null;renderQueue()};
  $('#message').onclick=()=>messageForm(item);$('#continueConversation').onclick=()=>messageForm(item);
  if(!terminal){$('#changeAssignee').onclick=()=>taskAssignmentForm(item,actors);$('#abandonItem').onclick=()=>taskAbandonForm(item);$('#primaryTaskAction').onclick=()=>item.stage==='todo'?taskAssignmentForm(item,actors):stageForm(item)}
};

function taskAssignmentForm(item,actors){
  const choices=actors.filter(actor=>actor.available).map(actor=>`<option value="${actor.kind}:${actor.id}" ${actor.kind===item.assignee_kind&&actor.id===item.assignee_id?'selected':''}>${escapeHTML(actor.name)} · ${t(actor.kind)}</option>`).join('');
  openDrawer(t('changeExecutor'),`<form class="form" id="drawerForm"><label class="field"><span>${t('executor')}</span><select name="assignee" required>${choices}</select></label>${area(t('assignmentReason'),'reason','',`required placeholder="${escapeHTML(t('assignmentReasonPlaceholder'))}"`)}<div class="form-error" hidden></div><button class="button primary" type="submit">${t('confirmAssignment')}</button></form>`,()=>wireForm('#drawerForm',data=>{const [assigneeKind,assigneeId]=data.assignee.split(':');return api(`/api/work-items/${item.id}/assign`,{method:'POST',body:JSON.stringify({assigneeKind,assigneeId,reason:data.reason,expectedVersion:item.version})})}));
}

function taskAbandonForm(item){
  openDrawer(t('abandonItem'),`<form class="form" id="drawerForm">${area(t('abandonReason'),'reason','',`required placeholder="${escapeHTML(t('abandonReasonPlaceholder'))}"`)}<div class="form-error" hidden></div><button class="button danger" type="submit">${t('confirmAbandon')}</button></form>`,()=>wireForm('#drawerForm',data=>api(`/api/work-items/${item.id}/abandon`,{method:'POST',body:JSON.stringify({reason:data.reason,expectedVersion:item.version})})));
}

async function renderAccount(){
  const actions=`<button class="button" id="signOut">${icon('log-out')}${t('logout')}</button>`;
  $('#workspace').innerHTML=header(t('account'),'',actions)+`<div class="content settings-grid"><section class="settings-section"><h2>${escapeHTML(state.me.displayName)}</h2><div class="kv"><div><dt>${t('username')}</dt><dd>${escapeHTML(state.me.username)}</dd></div><div><dt>${t('role')}</dt><dd>${t(state.me.systemRole)}</dd></div><div><dt>${t('status')}</dt><dd>${t(state.me.status)}</dd></div></div></section><section class="settings-section"><h2>${t('security')}</h2><button class="button" id="changePassword">${t('changePassword')}</button></section></div>`;
  $('#signOut').onclick=async()=>{await api('/api/auth/logout',{method:'POST',body:'{}'});state.me=null;renderLogin()};$('#changePassword').onclick=passwordForm;
}

