let renderProjectSettingsPage=renderSettings;
const queuePriorityRank={urgent:0,high:1,medium:2,low:3};
const queueStageRank={execution:0,discussion:1,acceptance:2,todo:3,completed:4,abandoned:5};

wireForm=function(selector,submit){const form=$(selector);form.onsubmit=async event=>{event.preventDefault();const button=$('button[type=submit]',form),error=$('.form-error',form);button.disabled=true;error.hidden=true;try{await submit(Object.fromEntries(new FormData(form)));closeDrawer();await loadProjects();renderShell()}catch(x){error.textContent=x.message;error.hidden=false;button.disabled=false}}};

renderShell=function(){
  syncDocumentLocale();
  const projectNav=[['queue','list'],['myQueue','check'],['projectSettings','settings']];
  const bottomNav=[['messages','bell'],['settings','settings']];
  const button=([page,name])=>`<button data-page="${page}" class="${state.page===page?'active':''}">${icon(name)}<span>${t(page)}</span></button>`;
  $('#app').innerHTML=`<div class="shell"><header class="mast"><div class="brand"><span class="brand-mark">PB</span><span>ProjectBoard</span></div><div class="mast-actions">${localeControl()}</div></header><div class="workspace-grid"><aside class="rail"><button class="project-switch" id="projectSwitch"><span class="project-mark">${state.project?escapeHTML(state.project.key.slice(0,2).toUpperCase()):'--'}</span><span><strong>${escapeHTML(state.project?.name||t('noProjects'))}</strong><small>${escapeHTML(state.project?.repositoryUrl||t('projectSetup'))}</small></span>${icon('chevron')}</button><nav class="nav rail-primary">${projectNav.map(button).join('')}</nav><nav class="nav rail-bottom">${bottomNav.map(button).join('')}</nav><div class="rail-foot">${t('footerRuntime')}<br>${t('footerEmbedded')}</div></aside><main class="workspace" id="workspace"></main></div></div><div class="drawer-backdrop" id="drawerBackdrop"></div><aside class="drawer" id="drawer" role="dialog" aria-modal="true" aria-hidden="true"></aside>`;
  document.querySelectorAll('[data-page]').forEach(element=>element.onclick=()=>navigate(element.dataset.page));
  wireLocaleControl();$('#projectSwitch').onclick=projectPicker;$('#drawerBackdrop').onclick=closeDrawer;document.addEventListener('keydown',escapeDrawer,{once:true});renderPage();
};

renderPage=async function(){
  const root=$('#workspace');root.innerHTML=`<div class="loading">${t('loading')}</div>`;
  try{
    if(state.page==='queue'||state.page==='myQueue')await renderQueue();
    else if(state.page==='members')await renderMembers();
    else if(state.page==='agents')await renderAgents();
    else if(state.page==='messages')await renderMessages();
    else if(state.page==='settings')await renderSettingsHub();
    else await renderQueue();
  }catch(error){root.innerHTML=header(t('loadFailed'),t('loadFailedNote'))+`<div class="content"><div class="form-error">${escapeHTML(error.message)}</div></div>`}
};

function queueMemberOption(actors,value,label){return `<option value="">${t(label)}</option>${actors.filter(actor=>actor.kind==='human').map(actor=>`<option value="${actor.id}" ${value===actor.id?'selected':''}>${escapeHTML(actor.name)}</option>`).join('')}`}

renderQueue=async function(){
  if(!state.project){$('#workspace').innerHTML=header(t('queue'),t('noProjectsNote'),`<button class="button primary" id="createProject">${icon('plus')}${t('createProject')}</button>`)+emptyState(t('noProjects'),t('noProjectsNote'));$('#createProject').onclick=projectForm;return}
  const [items,actors]=await Promise.all([api(`/api/work-items?projectId=${encodeURIComponent(state.project.id)}`),loadTaskActors()]);
  state.items=items;
  if(state.task){await renderTask();return}
  state.queueStage=state.queueStage||'all';state.queueQuery=state.queueQuery||'';state.queuePriority=state.queuePriority||'all';state.queueBlocker=state.queueBlocker||'any';state.expandedParents=state.expandedParents||new Set();
  state.queueCreator=state.queueCreator||'';state.queueAssignee=state.queueAssignee||'';state.queueFollower=state.queueFollower||'';state.queueRelated=state.queueRelated||'';state.queueCreatedByMe=Boolean(state.queueCreatedByMe);
  const mine=state.page==='myQueue';
  const filterActive=state.queueCreatedByMe||state.queuePriority!=='all'||state.queueBlocker!=='any'||state.queueCreator||state.queueAssignee||state.queueFollower||state.queueRelated;
  const stages=[['all','queueAll'],['todo','todo'],['discussion','discussion'],['execution','execution'],['acceptance','acceptance'],['completed','completed'],['order_closed','order_closed']];
  $('#workspace').innerHTML=`<header class="queue-page-head"><div class="queue-title"><div><span class="eyebrow">${mine?t('myQueue'):t('queue')}</span><h1>${mine?t('myQueue'):t('queue')}</h1><p>${mine?t('myQueueNote'):t('queueNote')}</p></div><button class="button primary" id="newItem">${icon('plus')}${t('createItem')}</button></div>${mine?'':`<div class="queue-tabs" role="tablist">${stages.map(([value,label])=>`<button class="queue-tab ${state.queueStage===value?'active':''}" data-queue-stage="${value}">${t(label)} <span>${value==='all'?items.length:items.filter(item=>item.stage===value).length}</span></button>`).join('')}</div>`}<div class="queue-tools"><label class="search">${icon('search')}<input id="queueSearch" value="${escapeHTML(state.queueQuery)}" placeholder="${t('search')}"></label>${mine?'':`<button class="button ${state.queueCreatedByMe?'active':''}" id="createdByMe" aria-pressed="${state.queueCreatedByMe}">${icon('user')}${t('createdByMe')}</button>`}<button class="button ${filterActive?'active':''}" id="queueFilter">${icon('filter')}${t(filterActive?'filterActive':'filter')}</button><span class="queue-count" id="queueCount"></span></div></header><div class="queue-content" id="queueList"></div>`;
  const matches=item=>{
    const query=state.queueQuery.trim().toLowerCase();
    const followers=item.follower_ids||[];
    const related=id=>item.created_by_user_id===id||(item.assignee_kind==='human'&&item.assignee_id===id)||followers.includes(id);
    return (!mine||(!['completed','abandoned'].includes(item.stage)&&item.assignee_kind==='human'&&item.assignee_id===state.me.id))&&(mine||state.queueStage==='all'||item.stage===state.queueStage)&&(!state.queueCreatedByMe||item.created_by_user_id===state.me.id)&&(!state.queueCreator||item.created_by_user_id===state.queueCreator)&&(!state.queueAssignee||item.assignee_id===state.queueAssignee)&&(!state.queueFollower||followers.includes(state.queueFollower))&&(!state.queueRelated||related(state.queueRelated))&&(state.queuePriority==='all'||item.priority===state.queuePriority)&&(state.queueBlocker==='any'||(state.queueBlocker==='blocked')===Boolean(item.blocked_at))&&(!query||`${item.id} ${item.title}`.toLowerCase().includes(query));
  };
  const paint=()=>{
    let visible=items.filter(matches);
    if(mine)visible.sort((a,b)=>Number(Boolean(b.blocked_at))-Number(Boolean(a.blocked_at))||(queuePriorityRank[a.priority]??9)-(queuePriorityRank[b.priority]??9)||(queueStageRank[a.stage]??9)-(queueStageRank[b.stage]??9)||new Date(a.updated_at)-new Date(b.updated_at));
    $('#queueCount').textContent=t('itemsCount',{count:visible.length});
    $('#queueList').innerHTML=visible.length?`<section class="queue-group"><div class="group-label">${mine?t('myQueue'):t('currentRoute',{count:visible.length})}</div>${visible.map(item=>taskRowMarkup(item,actors,{})).join('')}</section>`:`<section class="queue-empty"><strong>${t('noMatchingItems')}</strong><p>${t('noMatchingItemsNote')}</p></section>`;
    document.querySelectorAll('.work-row[data-id]').forEach(row=>row.onclick=()=>{state.task=row.dataset.id;renderQueue()});
  };
  paint();$('#newItem').onclick=workItemForm;$('#queueSearch').oninput=event=>{state.queueQuery=event.target.value;paint()};$('#queueFilter').onclick=()=>queuePeopleFilterForm(actors);
  const mineButton=$('#createdByMe');if(mineButton)mineButton.onclick=()=>{state.queueCreatedByMe=!state.queueCreatedByMe;renderQueue()};
  document.querySelectorAll('[data-queue-stage]').forEach(button=>button.onclick=()=>{state.queueStage=button.dataset.queueStage;renderQueue()});
};

