  const followers=activeMembers.map(member=>`<label class="member-check"><input type="checkbox" name="followerIds" value="${member.id}"><span class="task-avatar">${taskAvatar(member.displayName)}</span><span>${escapeHTML(member.displayName)}</span>${icon('check')}</label>`).join('');
  openDrawer(t('createItem'),`<form class="form" id="newWorkItemForm">${field(t('title'),'title','text','','required')}${area(t('description'),'descriptionMarkdown')}${area(t('acceptanceCriteria'),'acceptanceCriteriaMarkdown','','required')}<label class="field"><span>${t('priority')}</span><select name="priority"><option value="medium">${t('medium')}</option><option value="urgent">${t('urgent')}</option><option value="high">${t('high')}</option><option value="low">${t('low')}</option></select></label><label class="field"><span>${t('assignee')}</span><select name="assignee" required><option value="">${t('selectExecutor')}</option>${choices}</select></label><fieldset class="follower-field"><legend>${t('selectFollowers')}</legend><div class="member-check-list">${followers}</div></fieldset><div class="form-error" hidden></div><button class="button primary" type="submit">${t('createItem')}</button></form>`,()=>{
    $('#newWorkItemForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),error=$('.form-error',form),data=Object.fromEntries(new FormData(form));const [assigneeKind,assigneeId]=(data.assignee||'').split(':');button.disabled=true;error.hidden=true;try{await api('/api/work-items',{method:'POST',body:JSON.stringify({...data,assignee:undefined,followerIds:new FormData(form).getAll('followerIds'),assigneeKind,assigneeId,projectId:state.project.id,requestId:crypto.randomUUID()})});closeDrawer();await renderQueue()}catch(x){error.textContent=x.message;error.hidden=false;button.disabled=false}}
  });
