  const rows=enabled.map(member=>`<button class="table-row action management-row" data-member="${member.id}"><span><strong>${escapeHTML(member.displayName)}</strong><small>@${escapeHTML(member.username)}</small></span><span>${t(member.status)}</span><span>${t(member.systemRole)}</span><span class="row-end">${badge(t(member.role),'signal')}${icon('chevron')}</span></button>`).join('');
  $('#workspace').innerHTML=header(t('members'),t('membersDescription'),actions)+`<div class="content"><div class="table">${rows||`<div class="management-empty">${icon('users')}<strong>${t('noEnabledMembers')}</strong><p>${t('noEnabledMembersNote')}</p></div>`}</div></div>`;
