  const readAll=$('#markAllRead');if(readAll)readAll.onclick=async()=>{localStorage.pbDemoNotificationsRead=JSON.stringify(localDemoNotifications().map(item=>item.id));await api('/api/notifications/read-all',{method:'POST',body:'{}'});renderMessages()};
  document.querySelectorAll('[data-notification]').forEach(row=>row.onclick=async()=>{if(row.dataset.demo==='true'){const ids=new Set(JSON.parse(localStorage.pbDemoNotificationsRead||'[]'));ids.add(row.dataset.notification);localStorage.pbDemoNotificationsRead=JSON.stringify([...ids])}else await api(`/api/notifications/${row.dataset.notification}/read`,{method:'POST',body:'{}'});if(row.dataset.workItem){state.page='queue';state.task=row.dataset.workItem;renderShell()}else renderMessages()});
