taskModeLabel=function(mode){if(mode==='manual')return t('manualMode');if(mode==='auto')return t('automatic');if(mode==='human')return t('human');if(mode==='agent')return t('agent');return mode||t('notSet')};

function taskConfigurationMarkup(item,actors,isCreate=false){
  const members=actors.filter(actor=>actor.kind==='human'&&actor.available),assignees=actors.filter(actor=>actor.available),selected=item.follower_ids||[];
  return `<form class="form task-config-form" id="taskConfigForm"><section class="config-section"><header><span>${icon('list')}</span><div><h3>${t('basicInformation')}</h3><p>${t('taskConfigNote')}</p></div></header>${field(t('title'),'title','text',item.title||'','required')}${area(t('description'),'descriptionMarkdown',item.description_markdown||'')}${area(t('acceptanceCriteria'),'acceptanceCriteriaMarkdown',item.acceptance_criteria_markdown||'','required')}<div class="config-grid"><label class="field"><span>${t('priority')}</span><select name="priority">${['urgent','high','medium','low'].map(value=>`<option value="${value}" ${item.priority===value?'selected':''}>${t(value)}</option>`).join('')}</select></label><label class="field"><span>${t('targetBranch')}</span><input name="targetBranch" value="${escapeHTML(item.target_branch||state.project.defaultTargetBranch||'main')}"></label></div></section><section class="config-section"><header><span>${icon('activity')}</span><div><h3>${t('workflowConfiguration')}</h3><p>${t('automaticProgression')}</p></div></header><div class="config-grid"><label class="field"><span>${t('assignee')}</span><select name="assignee"><option value="">${t('unassigned')}</option>${assignees.map(actor=>`<option value="${actor.kind}:${actor.id}" ${item.assignee_kind===actor.kind&&item.assignee_id===actor.id?'selected':''}>${escapeHTML(actor.name)} · ${actor.kind==='agent'?'Agent':t('human')}</option>`).join('')}</select></label><label class="field"><span>${t('currentStage')}</span><select name="stage">${['todo','discussion','execution','acceptance'].map(value=>`<option value="${value}" ${item.stage===value?'selected':''}>${t(value)}</option>`).join('')}</select></label></div><div class="mode-grid">${[['discussionMode','discussion_mode',['manual','auto']],['executionMode','execution_mode',['manual','auto']],['acceptanceMode','acceptance_mode',['human','agent','auto']]].map(([label,key,values])=>`<label class="field"><span>${t(label)}</span><select name="${label}">${values.map(value=>`<option value="${value}" ${item[key]===value?'selected':''}>${taskModeLabel(value)}</option>`).join('')}</select></label>`).join('')}</div></section><section class="config-section follower-config"><header><span>${icon('users')}</span><div><h3>${t('followers')}</h3><p>${t('followerPickerHint')}</p></div></header><div class="follower-chips" id="followerChips"></div><div id="followerInputs"></div><label class="follower-add"><span class="sr-only">${t('addFollower')}</span><select id="configFollowerSelect"></select></label></section>${isCreate?'':`<section class="config-section config-danger"><header><span>${icon('shield')}</span><div><h3>${t('stageAction')}</h3><p>${item.blocked_at?escapeHTML(item.blocked_reason||t('blocked')):t('noBlocker')}</p></div></header><div class="drawer-actions"><button class="button" type="button" id="configBlockTask">${t(item.blocked_at?'clearBlocked':'blockTask')}</button><button class="button danger" type="button" id="configAbandonTask">${t('abandonItem')}</button></div></section>`}<div class="form-error" hidden></div><button class="button primary config-save" type="submit">${t(isCreate?'createItem':'save')}</button></form>`;
}
function wireTaskConfiguration(item,actors,isCreate=false){
  const form=$('#taskConfigForm'),members=actors.filter(actor=>actor.kind==='human'&&actor.available),selected=new Set(item.follower_ids||[]),chips=$('#followerChips'),inputs=$('#followerInputs'),select=$('#configFollowerSelect');
  const paint=()=>{chips.innerHTML=selected.size?[...selected].map(id=>{const member=members.find(value=>value.id===id);return member?`<span>${escapeHTML(member.name)}<button type="button" data-remove-follower="${id}" aria-label="${t('removeFollower')}">${icon('x')}</button></span>`:''}).join(''):`<small>${t('noFollowers')}</small>`;inputs.innerHTML=[...selected].map(id=>`<input type="hidden" name="followerIds" value="${id}">`).join('');const available=members.filter(member=>!selected.has(member.id));select.innerHTML=`<option value="">${available.length?`＋ ${t('addFollower')}`:t('allMembersEnabled')}</option>${available.map(member=>`<option value="${member.id}">${escapeHTML(member.name)}</option>`).join('')}`;select.disabled=!available.length;chips.querySelectorAll('[data-remove-follower]').forEach(button=>button.onclick=()=>{selected.delete(button.dataset.removeFollower);paint()})};select.onchange=()=>{if(select.value){selected.add(select.value);paint()}};paint();
  if(!isCreate){const block=$('#configBlockTask'),abandon=$('#configAbandonTask');if(block)block.onclick=()=>item.blocked_at?stageForm(item):taskBlockForm(item);if(abandon)abandon.onclick=()=>taskAbandonForm(item)}
  form.onsubmit=async event=>{event.preventDefault();const button=$('button[type=submit]',form),error=$('.form-error',form),data=Object.fromEntries(new FormData(form)),[assigneeKind,assigneeId]=(data.assignee||'').split(':');button.disabled=true;error.hidden=true;const payload={...data,assignee:undefined,assigneeKind:assigneeKind||'',assigneeId:assigneeId||'',followerIds:[...selected]};try{if(isCreate){await api('/api/work-items',{method:'POST',body:JSON.stringify({...payload,projectId:state.project.id,requestId:crypto.randomUUID()})});closeDrawer();await renderQueue()}else{await api(`/api/work-items/${item.id}`,{method:'PATCH',body:JSON.stringify({...payload,configure:true,expectedVersion:item.version})});closeDrawer();await renderTask()}}catch(x){error.textContent=x.message;error.hidden=false;button.disabled=false}}
}
function taskConfigurationForm(item,actors){openDrawer(t('taskConfiguration'),taskConfigurationMarkup(item,actors,false),()=>wireTaskConfiguration(item,actors,false))}
workItemForm=async function(){const actors=await loadTaskActors();const draft={title:'',description_markdown:'',acceptance_criteria_markdown:'',priority:'medium',target_branch:state.project.defaultTargetBranch,stage:'todo',discussion_mode:state.project.discussionMode||'manual',execution_mode:state.project.executionMode||'manual',acceptance_mode:state.project.acceptanceMode||'human',follower_ids:[]};openDrawer(t('createItem'),taskConfigurationMarkup(draft,actors,true),()=>wireTaskConfiguration(draft,actors,true))};

renderTask=async function(){
  const [item,actors]=await Promise.all([api(`/api/work-items/${state.task}`),loadTaskActors()]),assignee=taskAssignee(item,actors),terminal=['completed','order_closed','abandoned'].includes(item.stage),followers=item.follower_ids||[],creator=taskPersonName(item.created_by_user_id,actors),criteria=(item.acceptance_criteria_markdown||'').split(/\r?\n/).filter(line=>line.trim());
  const attachmentByEntry=new Map();(item.attachments||[]).forEach(a=>{if(a.entry_id){const list=attachmentByEntry.get(a.entry_id)||[];list.push(a);attachmentByEntry.set(a.entry_id,list)}});(item.conversation||[]).forEach(event=>event.attachments=attachmentByEntry.get(event.id)||[]);
  $('#workspace').innerHTML=`<div class="wechat-task"><header class="chat-header"><button class="back-link" id="back">${icon('chevron')}${t(state.page==='myQueue'?'myQueue':'queue')}</button><div class="chat-title"><div><span>${escapeHTML(item.id)} · ${t('version',{version:item.version})}</span><h1>${escapeHTML(item.title)}</h1></div><div class="chat-header-actions"><button class="button primary" id="configureTask" ${terminal?'disabled':''}>${icon('settings')}${t('configure')}</button></div></div><div class="chat-members"><span>${t('assignee')}</span><span class="task-avatar">${taskAvatar(assignee.name)}</span><strong>${escapeHTML(assignee.name)}</strong><i></i><span>${t('creator')} ${escapeHTML(creator)}</span><i></i><span>${t('followers')} ${followers.length}</span><span class="chat-stage">${badge(t(item.stage),'signal')}${badge(t(item.priority))}${item.blocked_at?badge(t('blocked'),'danger'):''}</span></div><div class="task-route-compact"><div><span>${t('routeProgress')}</span><strong>${t(item.stage)}</strong></div><div class="phase-band" role="list">${phaseMarkup(item)}</div></div></header><main class="chat-canvas"><section class="chat-context"><div class="context-message"><span class="entry-avatar system-avatar">${icon('message')}</span><div><strong>${t('workItemContext')}</strong><p>${escapeHTML(item.description_markdown||t('noDescription'))}</p></div></div><details class="task-facts"><summary>${icon('list')}${t('taskData')}</summary><dl><div><dt>${t('targetBranch')}</dt><dd><code>${escapeHTML(item.target_branch)}</code></dd></div><div><dt>${t('discussionMode')}</dt><dd>${taskModeLabel(item.discussion_mode)}</dd></div><div><dt>${t('executionMode')}</dt><dd>${taskModeLabel(item.execution_mode)}</dd></div><div><dt>${t('acceptanceMode')}</dt><dd>${taskModeLabel(item.acceptance_mode)}</dd></div><div><dt>${t('updated')}</dt><dd>${taskDate(item.updated_at)}</dd></div><div><dt>${t('dependencies')}</dt><dd>${escapeHTML((item.dependencies||[]).join(', ')||t('none'))}</dd></div></dl>${taskEvidenceMarkup(item)}</details><div class="criteria-message"><div class="criteria-head"><div><strong>${t('acceptanceCriteria')}</strong><small>${t('criteriaDuringWork')}</small></div></div>${criteria.length?`<ol>${criteria.map(line=>`<li><span>${icon('check')}</span><p>${escapeHTML(line.replace(/^[-*]\s*/,''))}</p></li>`).join('')}</ol>`:`<p>${t('noCriteria')}</p>`}</div></section><section class="chat-history">${(item.conversation||[]).map(event=>chatEventMarkup(event,actors)).join('')||`<p class="conversation-empty">${t('noEvents')}</p>`}</section></main><form class="chat-composer" id="chatComposer"><div class="composer-main"><div class="pending-attachments" id="pendingAttachments" hidden></div><textarea name="markdown" rows="1" placeholder="${t('conversationPlaceholder')}"></textarea><small class="composer-hint">${t('composerHint')}</small></div><label class="attachment-button" title="${t('addAttachment')}">${icon('paperclip')}<input id="attachmentInput" type="file" multiple accept="image/*,.md,.markdown,.txt,.pdf,.zip,.json,.csv"></label><button class="button primary composer-send" type="submit">${icon('chevron')}${t('send')}</button></form></div>`;
  $('#back').onclick=()=>{state.task=null;renderQueue()};const config=$('#configureTask');if(config)config.onclick=()=>taskConfigurationForm(item,actors);let pendingFiles=[];const input=$('#attachmentInput'),pending=$('#pendingAttachments');input.onchange=()=>{pendingFiles=[...input.files];pending.hidden=!pendingFiles.length;pending.innerHTML=pendingFiles.map((file,index)=>`<span>${icon(file.type.startsWith('image/')?'image':'file')}<span>${escapeHTML(file.name)}<small>${formatFileSize(file.size)}</small></span><button type="button" data-remove-file="${index}">${icon('x')}</button></span>`).join('');pending.querySelectorAll('[data-remove-file]').forEach(button=>button.onclick=()=>{pendingFiles.splice(Number(button.dataset.removeFile),1);button.parentElement.remove();pending.hidden=!pendingFiles.length})};wireMarkdownPreviews();const composerForm=$('#chatComposer'),composerInput=$('textarea',composerForm);composerInput.onkeydown=event=>{if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();composerForm.requestSubmit()}};composerForm.onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),markdown=new FormData(form).get('markdown');if(!String(markdown).trim()&&!pendingFiles.length)return toast(t('messageOrAttachmentRequired'));button.disabled=true;try{const attachmentIds=[];for(const file of pendingFiles){const body=new FormData();body.append('file',file);const uploaded=await api(`/api/work-items/${item.id}/attachments`,{method:'POST',body});attachmentIds.push(uploaded.id)}await api(`/api/work-items/${item.id}/messages`,{method:'POST',body:JSON.stringify({markdown,attachmentIds,expectedVersion:item.version})});await renderTask()}catch(error){toast(error.message);button.disabled=false}};
};

const legacyRenderUsers=renderUsers,legacyRenderUserSettings=renderUserSettings;
renderUsers=async function(){await legacyRenderUsers();document.querySelectorAll('.user-row small').forEach(node=>node.textContent=node.textContent.replace(/^@/,''))};
renderUserSettings=function(user){legacyRenderUserSettings(user);const eyebrow=$('.drawer-head .eyebrow'),input=$('#userSettingsForm input[disabled]');if(eyebrow)eyebrow.textContent=eyebrow.textContent.replace(' / @',' / ');if(input)input.value=input.value.replace(/^@/,'')};

renderSettingsHub=async function(){state.settingsSection=state.settingsSection==='project'?'account':state.settingsSection||'account';const admin=state.me.systemRole==='administrator',sections=[['account','settingsAccount'],...(admin?[['agentsManagement','settingsAgents'],['users','settingsUsers'],['projects','settingsProjects'],['audit','settingsAudit'],['system','settingsSystem']]:[])],renderer={account:renderAccount,agentsManagement:renderAgentManagement,users:renderUsers,projects:renderProjects,audit:renderActivity,system:renderSystemSettings}[state.settingsSection]||renderAccount;await renderer();const tabs=document.createElement('div');tabs.className='settings-hub-tabs';tabs.innerHTML=sections.map(([key,label])=>`<button class="${state.settingsSection===key?'active':''}" data-setting-section="${key}">${t(label)}</button>`).join('');$('#workspace').prepend(tabs);tabs.querySelectorAll('button').forEach(button=>button.onclick=()=>{state.settingsSection=button.dataset.settingSection;renderSettingsHub()})};

renderShell=function(){syncDocumentLocale();const projectNav=[['queue','list'],['myQueue','check'],['projectSettings','settings']],bottomNav=[['messages','bell'],['settings','settings']],button=([page,name])=>`<button data-page="${page}" class="${state.page===page?'active':''}">${icon(name)}<span>${t(page)}</span></button>`;$('#app').innerHTML=`<div class="shell"><header class="mast"><div class="brand"><span class="brand-mark">PB</span><span>ProjectBoard</span></div><div class="mast-actions">${localeControl()}</div></header><div class="workspace-grid"><aside class="rail"><button class="project-switch" id="projectSwitch"><span class="project-mark">${state.project?escapeHTML(state.project.key.slice(0,2).toUpperCase()):'--'}</span><span><strong>${escapeHTML(state.project?.name||t('noProjects'))}</strong><small>${escapeHTML(state.project?.repositoryUrl||t('projectSetup'))}</small></span>${icon('chevron')}</button><nav class="nav rail-primary">${projectNav.map(button).join('')}</nav><nav class="nav rail-bottom">${bottomNav.map(button).join('')}</nav><div class="rail-foot">${t('footerRuntime')}<br>${t('footerEmbedded')}</div></aside><main class="workspace" id="workspace"></main></div></div><div class="drawer-backdrop" id="drawerBackdrop"></div><aside class="drawer" id="drawer" role="dialog" aria-modal="true" aria-hidden="true"></aside>`;document.querySelectorAll('[data-page]').forEach(element=>element.onclick=()=>navigate(element.dataset.page));wireLocaleControl();$('#projectSwitch').onclick=projectPicker;$('#drawerBackdrop').onclick=closeDrawer;document.addEventListener('keydown',escapeDrawer,{once:true});renderPage()};
renderPage=async function(){const root=$('#workspace');root.innerHTML=`<div class="loading">${t('loading')}</div>`;try{if(state.page==='queue'||state.page==='myQueue')await renderQueue();else if(state.page==='members')await renderMembers();else if(state.page==='agents')await renderAgents();else if(state.page==='projectSettings')await renderProjectSettingsPage();else if(state.page==='messages')await renderMessages();else if(state.page==='settings')await renderSettingsHub();else await renderQueue()}catch(error){root.innerHTML=header(t('loadFailed'),t('loadFailedNote'))+`<div class="content"><div class="form-error">${escapeHTML(error.message)}</div></div>`}};

const priorProjectSettingsPage=renderProjectSettingsPage;
renderProjectSettingsPage=async function(){await priorProjectSettingsPage();const title=$('.page-head h1');if(title)title.textContent=t('projectSettings');const sync=$('#syncCommits');if(sync){sync.innerHTML=`${icon('activity')}${t('syncCommits')}`;const replacement=sync.cloneNode(true);sync.replaceWith(replacement);replacement.onclick=async()=>{replacement.disabled=true;try{const result=await api(`/api/projects/${state.project.id}/sync-commits`,{method:'POST',body:'{}'});toast(result.skipped==='no_work_items'?t('noWorkItemsSync'):result.skipped==='no_commits'?t('noCommitsSync'):t('syncResult',{fetched:result.fetched,inserted:result.inserted}));await renderProjectSettingsPage()}catch(error){toast(error.message)}finally{replacement.disabled=false}}}const identity=$('.settings-project-identity');if(identity){const stamp=document.createElement('div');stamp.className='project-sync-stamp';let grant=null;try{grant=await api(`/api/projects/${state.project.id}/repository-grant`)}catch{}stamp.innerHTML=`<span>${t('lastSyncedAt')}</span><strong>${grant?.lastSyncAt?taskDate(grant.lastSyncAt):t('notSynced')}</strong>`;identity.append(stamp)}};

Object.assign(messages.zh,{order_closed:'订单关闭',advanceStage:'推进阶段',targetStage:'目标阶段',changeStageNote:'阶段变更说明',changeStageHint:'可前进或回退到任意其他阶段。',switchToStage:'切换至{stage}',stageChangedToast:'任务已切换至{stage}阶段',allowAgentExecution:'允许 Agent 执行',allowAgentExecutionNote:'控制 Agent 是否能自动接取任务，并继续处理讨论、执行与验收阶段。',allowAgentAutoClose:'允许 Agent 自动关闭任务',allowAgentAutoCloseNote:'允许 Agent 在任务完成后自动推进至订单关闭。',allowSubtasks:'允许子任务',allowSubtasksNote:'默认开启。Agent 可按任务规模创建多个并列子任务。',allowAgentAutoCloseSubtasks:'允许 Agent 自动关闭子任务',allowAgentAutoCloseSubtasksNote:'允许 Agent 在子任务完成后自动关闭子任务。',agentCommonPrompts:'Agent 通用提示词',agentCommonPromptsNote:'每次项目内 Agent 对话都会读取这些提示词。',managePrompts:'管理提示词',addPrompt:'新增提示词',promptPlaceholder:'输入一条项目内长期有效的工作约束…',automation:'自动化',repositoryAndBranches:'仓库与分支',keyEffective:'Key 生效中',keyInactive:'Key 未生效',sshConnected:'Codex 已连接',sshDisconnected:'Codex 未连接',removeFromProject:'移出项目',confirmRemove:'确认移出',projectMembers:'项目成员',projectAgents:'Agent 身份',saveAutomation:'保存自动化设置'});
