function agentForm(){openDrawer(t('createAgent'),formShell(field(t('name'),'name','text','','required')+area(t('purpose'),'purpose','','required')),()=>{$('#drawerForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),error=$('.form-error',form);button.disabled=true;try{const agent=await api('/api/agents',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});await loadProjects();setTimeout(()=>agentSSHDrawer(agent),0)}catch(x){error.textContent=x.message;error.hidden=false;button.disabled=false}}})}

async function agentSSHDrawer(agent){
  const [keys,sshInfo]=await Promise.all([api(`/api/agents/${agent.id}/ssh-keys`),api('/api/system/ssh')]);
  const knownHosts=`[${sshInfo.host}]:${sshInfo.port} ${sshInfo.hostKey}`;
  const configSnippet=`[mcp_servers.projectboard]\ncommand = "ssh"\nargs = ["-T", "-p", "${sshInfo.port}", "-i", "/absolute/path/projectboard_agent", "${agent.id}@${sshInfo.host}", "projectboard-mcp"]\nstartup_timeout_sec = 20\ntool_timeout_sec = 70`;
  const continuousPrompt='连接 ProjectBoard，先恢复有效 execution；否则持续等待并领取任务。自主准备仓库与环境，维护心跳，记录命令、进度、验证和交付；失败时回写阻塞并释放，然后继续下一项。直到我明确取消前不要结束循环。';
  const activeKeys=keys.filter(key=>!key.revokedAt),keygenCommand='ssh-keygen -t ed25519 -f ~/.ssh/projectboard_agent';
  const rows=activeKeys.map(key=>`<div class="agent-key-row"><span class="agent-key-mark">${icon('key')}</span><span class="agent-key-copy"><strong>${escapeHTML(key.label)}</strong><code>${escapeHTML(key.fingerprint)}</code><small>${t('created')} ${taskDate(key.createdAt)} · ${t('lastUsed')} ${key.lastUsedAt?taskDate(key.lastUsedAt):t('neverUsed')}</small></span><span class="agent-key-actions">${key.connected?`<span class="agent-session-state connected"><i></i>${t('onlineSession')}</span>`:''}<button class="text-action danger" type="button" data-revoke-key="${key.id}">${t('revoke')}</button></span></div>`).join('');
  const copyBlock=(id,label,value)=>`<div class="agent-copy-block"><code>${escapeHTML(value)}</code><button class="button" type="button" id="${id}">${icon('copy')}${label}</button></div>`;
  openDrawer(t('agentKeyManagement'),`<section class="agent-ssh-identity"><span class="agent-ssh-avatar">${icon('bot')}</span><div class="agent-ssh-name"><span>${t('agentSecurityState')}</span><h3>${escapeHTML(agent.name)}</h3><p>${escapeHTML(agent.purpose||t('noPurpose'))}</p></div><div class="agent-ssh-status"><span class="agent-session-state ${agent.connected?'connected':''}"><i></i>${t(agent.connected?'sshConnected':'sshDisconnected')}</span>${agent.connected?`<button class="text-action danger" id="disconnectAgent" type="button">${t('disconnectAgent')}</button>`:''}</div><div class="agent-id-line"><span>${t('agentId')}</span><code>${escapeHTML(agent.id)}</code></div></section><section class="agent-ssh-section"><header class="agent-section-head"><div><h3>${t('registeredKeys')}</h3><p>${t('registeredKeysNote')}</p></div><span class="agent-count">${t('keyCount',{count:activeKeys.length})}</span></header><div class="agent-key-list">${rows||`<div class="agent-key-empty"><span class="agent-key-mark">${icon('key')}</span><div><strong>${t('noKeysTitle')}</strong><p>${t('noKeysNote')}</p></div></div>`}</div><details class="agent-key-entry" ${activeKeys.length?'':'open'}><summary>${icon('plus')}<span>${t(activeKeys.length?'addAnotherSSHKey':'addFirstSSHKey')}</span>${icon('chevron')}</summary><div class="agent-key-entry-body"><div class="agent-key-command"><span><strong>${t('generateKeyPair')}</strong><small>${t('privateKeyStaysLocal')}</small></span><code>${escapeHTML(keygenCommand)}</code><button class="button" type="button" id="copyKeygenCommand">${icon('copy')}${t('copyCommand')}</button></div><form class="form" id="sshKeyForm">${field(t('keyLabel'),'label','text','','required autocomplete="off"')}${area(t('publicKey'),'publicKey','','required spellcheck="false" placeholder="ssh-ed25519 AAAA…"')}<div class="form-error" hidden></div><button class="button primary agent-key-submit" type="submit">${icon('plus')}${t('addSSHKey')}</button></form></div></details></section><section class="agent-ssh-section agent-connect-section"><header class="agent-section-head"><div><h3>${t('connectionRecipe')}</h3><p>${t('connectionRecipeNote')}</p></div><a class="text-action" href="/docs/agent-execution.md" target="_blank" rel="noopener">${t('openAgentGuide')}${icon('chevron')}</a></header><div class="agent-connection-steps"><article class="agent-connection-step"><span class="agent-step-number">1</span><div><h4>${t('pinHost')}</h4><p>${t('pinHostNote')}</p><div class="agent-host-fingerprint"><span>${t('fingerprint')}</span><code>${escapeHTML(sshInfo.hostKeyFingerprint)}</code></div>${copyBlock('copyKnownHosts',t('copyKnownHosts'),knownHosts)}</div></article><article class="agent-connection-step"><span class="agent-step-number">2</span><div><h4>${t('configureCodex')}</h4><p>${t('configureCodexNote')}</p>${copyBlock('copyCodexConfig',t('copyConfig'),configSnippet)}</div></article><article class="agent-connection-step"><span class="agent-step-number">3</span><div><h4>${t('startAgentLoop')}</h4><p>${t('startAgentLoopNote')}</p>${copyBlock('copyAgentPrompt',t('copyPrompt'),continuousPrompt)}</div></article></div></section>`,drawer=>{
    drawer.classList.add('agent-ssh-drawer');
    $('#sshKeyForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),error=$('.form-error',form);button.disabled=true;try{await api(`/api/agents/${agent.id}/ssh-keys`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});closeDrawer();await agentSSHDrawer(agent)}catch(x){error.textContent=x.message;error.hidden=false;button.disabled=false}};
    $('#copyKeygenCommand').onclick=async()=>{await navigator.clipboard.writeText(keygenCommand);toast(t('copyCommand'))};
    $('#copyKnownHosts').onclick=async()=>{await navigator.clipboard.writeText(knownHosts);toast(t('copy'))};
    $('#copyCodexConfig').onclick=async()=>{await navigator.clipboard.writeText(configSnippet);toast(t('copy'))};
    $('#copyAgentPrompt').onclick=async()=>{await navigator.clipboard.writeText(continuousPrompt);toast(t('copy'))};
    drawer.querySelectorAll('[data-revoke-key]').forEach(button=>button.onclick=async()=>{if(!confirm(t('confirmRevokeKey')))return;button.disabled=true;await api(`/api/agents/${agent.id}/ssh-keys/${button.dataset.revokeKey}`,{method:'DELETE',body:'{}'});closeDrawer();await agentSSHDrawer(agent)});
    const disconnect=$('#disconnectAgent');if(disconnect)disconnect.onclick=async()=>{if(!confirm(t('confirmDisconnectAgent')))return;disconnect.disabled=true;await api(`/api/agents/${agent.id}/disconnect`,{method:'POST',body:'{}'});closeDrawer();await renderAgentManagement()};
  });
}

async function renderAgentManagement(){const agents=await api('/api/agents'),actions=`<button class="button primary" id="createManagedAgent">${icon('plus')}${t('createAgent')}</button>`;const rows=agents.map(agent=>`<button class="agent-fleet-row" data-managed-agent="${agent.id}"><span class="agent-fleet-avatar">${icon('bot')}</span><span class="agent-fleet-identity"><strong>${escapeHTML(agent.name)}</strong><small>${escapeHTML(agent.purpose||t('noPurpose'))}</small><code>${escapeHTML(agent.id)}</code></span><span class="agent-fleet-security"><span class="agent-key-total">${icon('key')}<strong>${agent.sshKeyCount}</strong><small>${t('sshKeys')}</small></span><span class="agent-session-state ${agent.connected?'connected':''}"><i></i>${t(agent.connected?'sshConnected':'sshDisconnected')}</span></span><span class="agent-fleet-arrow">${icon('chevron')}</span></button>`).join('');$('#workspace').innerHTML=header(t('agentKeyManagement'),t('agentKeyNote'),actions)+`<div class="content agent-management-content"><p class="agent-list-note">${t('agentListNote')}</p><div class="agent-fleet">${rows||emptyState(t('agentKeyManagement'),t('agentKeyNote'))}</div></div>`;$('#createManagedAgent').onclick=agentForm;document.querySelectorAll('[data-managed-agent]').forEach(row=>row.onclick=()=>agentSSHDrawer(agents.find(agent=>agent.id===row.dataset.managedAgent)))}

function agentSettings(agent){openDrawer(t('agentSettings'),`<section class="entity-summary"><span class="entity-mark">${icon('bot')}</span><div><span class="eyebrow">${t('agentIdentity')}</span><h3>${escapeHTML(agent.name)}</h3><div>${badge(t(agent.status))} ${badge(t(agent.connected?'sshConnected':'sshDisconnected'),agent.connected?'signal':'')}</div></div></section><section class="drawer-section"><span class="eyebrow">${t('purpose')}</span><p>${escapeHTML(agent.purpose||t('noPurpose'))}</p></section><form class="form" id="agentGrantForm">${projectPolicySwitch('allowUnassignedClaim','allowUnassignedClaim','allowUnassignedClaimNote',agent.allowUnassignedClaim)}<div class="form-error" hidden></div><button class="button primary" type="submit">${t('save')}</button></form><section class="drawer-section"><button class="button danger" id="removeAgentGrant">${t('disableForProject')}</button></section>`,()=>{$('#agentGrantForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget;await api(`/api/projects/${state.project.id}/agents/${agent.id}`,{method:'PUT',body:JSON.stringify({allowUnassignedClaim:new FormData(form).has('allowUnassignedClaim')})});closeDrawer();renderProjectSettingsPage()};$('#removeAgentGrant').onclick=()=>confirmProjectRemoval('agent',agent)})}

grantForm=async function(){const [configuration,settings,auths]=await Promise.all([api('/api/git/connections'),api('/api/git/provider-settings'),api('/api/provider-authorizations')]);const configured=configuration.github?.configured;const reusable=auths.filter(a=>a.provider==='github'&&a.status==='active').map(a=>`<button class="connection-provider compact" type="button" data-reuse-authorization="${a.id}"><span><strong>${escapeHTML(a.name)}</strong><small>GitHub · ${t('projectGrants',{count:a.bindingCount})}</small></span>${icon('chevron')}</button>`).join('');openDrawer(t('automaticGitSetup'),`<p class="drawer-note">${t('automaticGitNote')}</p><section class="connection-section"><div class="connection-options"><button class="connection-provider" type="button" ${configured?'data-connect-provider="github"':'data-config-provider="github"'}><span class="entity-mark">${icon(configured?'git':'settings')}</span><span><strong>${t(configured?'connectGitHub':'setupGitHub')}</strong><small>${t(configured?'continueProvider':'githubSetupCopy')}</small></span>${configured?badge(t('ready'),'signal'):badge(t('setupRequired'))}${icon('chevron')}</button></div></section>${reusable?`<section class="drawer-section"><span class="eyebrow">${t('reuseVerifiedConnection')}</span><div class="connection-options">${reusable}</div></section>`:''}`,drawer=>{drawer.querySelector('[data-connect-provider]')?.addEventListener('click',()=>startGitConnection('github'));drawer.querySelector('[data-config-provider]')?.addEventListener('click',()=>githubQuickSetup(settings.github||{}));drawer.querySelectorAll('[data-reuse-authorization]').forEach(button=>button.onclick=()=>reuseAuthorization(button.dataset.reuseAuthorization,auths.find(a=>a.id===button.dataset.reuseAuthorization)))})};
providerSettingsForm=function(_provider,current={}){return githubQuickSetup(current)};

renderSystemSettings=async function(){const [settings,sshInfo]=await Promise.all([api('/api/system/settings'),api('/api/system/ssh')]);const value=settings.publicUrl||location.origin;$('#workspace').innerHTML=header(t('globalSettings'),'HTTPS callbacks and the pinned Agent SSH identity.')+`<div class="content system-settings"><section class="settings-section"><h2>ProjectBoard address</h2><form class="form" id="systemSettingsForm">${field('ProjectBoard URL','publicUrl','url',value,'required')}<div class="form-error" hidden></div><button class="button primary" type="submit">${t('save')}</button></form></section><section class="settings-section"><h2>Agent SSH</h2><div class="kv"><div><dt>Address</dt><dd><code>${escapeHTML(sshInfo.host)}:${escapeHTML(sshInfo.port)}</code></dd></div><div><dt>${t('fingerprint')}</dt><dd><code>${escapeHTML(sshInfo.hostKeyFingerprint)}</code></dd></div></div><p><a class="text-action" href="/docs/agent-execution.md" target="_blank" rel="noopener">${t('openAgentGuide')}</a></p></section><section class="settings-section"><h2>GitHub</h2><p>Repository access uses a GitHub App. Agent write credentials are execution-scoped, single-repository, short-lived, and never persisted.</p></section></div>`;$('#systemSettingsForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),error=$('.form-error',form);button.disabled=true;try{await api('/api/system/settings',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(form)))});toast(t('systemSettingsSaved'));renderSystemSettings()}catch(x){error.textContent=x.message;error.hidden=false;button.disabled=false}}};

