function settingsCardHead(title,note,action=''){return `<header class="settings-card-head"><div><h2>${title}</h2>${note?`<p>${note}</p>`:''}</div>${action}</header>`}
function settingsSummaryRow(label,value,action=''){return `<div><dt>${label}</dt><dd>${value}</dd>${action}</div>`}
function policySummary(label,enabled){return `<div class="settings-policy-summary">${icon(enabled?'check':'x')}<span>${t(label)}</span><small>${t(enabled?'enabledState':'disabledState')}</small></div>`}

function accountProfileDrawer(){
  openDrawer(t('editProfile'),`<form class="form" id="accountProfileForm">${field(t('displayName'),'displayName','text',state.me.displayName,'required')}<label class="field"><span>${t('username')}</span><input value="${escapeHTML(state.me.username)}" disabled></label><label class="field"><span>${t('interfaceLanguage')}</span><select name="locale"><option value="zh" ${state.locale==='zh'?'selected':''}>简体中文</option><option value="en" ${state.locale==='en'?'selected':''}>English</option></select></label><div class="form-error" hidden></div><button class="button primary" type="submit">${t('save')}</button></form>`,()=>{$('#accountProfileForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),error=$('.form-error',form),data=Object.fromEntries(new FormData(form));button.disabled=true;error.hidden=true;try{const saved=await api('/api/me',{method:'PATCH',body:JSON.stringify({displayName:data.displayName})});state.me={...state.me,...saved,displayName:data.displayName};state.locale=data.locale;localStorage.pbLocale=data.locale;closeDrawer();renderShell()}catch(x){error.textContent=x.message;error.hidden=false;button.disabled=false}}});
}

renderAccount=async function(){
  const actions=`<button class="button" id="signOut">${icon('log-out')}${t('logout')}</button>`;
  $('#workspace').innerHTML=header(t('account'),'')+`<div class="content settings-page-shell"><div class="settings-status-line">${icon('shield')}<strong>${t('accountStatusNormal')}</strong><span>${t(state.me.status)}</span></div><section class="settings-card">${settingsCardHead(t('basicInformation'),t('profileDescription'),`<button class="button" id="editAccountProfile">${icon('settings')}${t('editProfile')}</button>`)}<dl class="settings-summary-rows">${settingsSummaryRow(t('displayName'),escapeHTML(state.me.displayName))}${settingsSummaryRow(t('username'),`<code>${escapeHTML(state.me.username)}</code>`)}${settingsSummaryRow(t('role'),t(state.me.systemRole))}${settingsSummaryRow(t('interfaceLanguage'),state.locale==='zh'?'简体中文':'English')}</dl></section><section class="settings-card">${settingsCardHead(t('passwordAndSessions'),t('accountPasswordNote'),`<button class="button" id="editAccountPassword">${icon('shield')}${t('editPassword')}</button>`)}<dl class="settings-summary-rows">${settingsSummaryRow(t('password'),t('passwordLastUpdated'))}${settingsSummaryRow(t('activeSession'),t('current'))}</dl><div class="settings-card-actions">${actions}</div></section></div>`;
  $('#editAccountProfile').onclick=accountProfileDrawer;$('#editAccountPassword').onclick=passwordForm;$('#signOut').onclick=async()=>{await api('/api/auth/logout',{method:'POST',body:'{}'});state.me=null;renderLogin()};
};

function projectPolicyDrawer(project){
  openDrawer(t('editPolicy'),`<form class="form" id="projectPolicyDrawerForm">${projectPolicySwitch('allowAgentExecution','allowAgentExecution','allowAgentExecutionNote',project.allowAgentExecution)}${projectPolicySwitch('allowAgentAutoClose','allowAgentAutoClose','allowAgentAutoCloseNote',project.allowAgentAutoClose)}${projectPolicySwitch('allowSubtasks','allowSubtasks','allowSubtasksNote',project.allowSubtasks)}${projectPolicySwitch('allowAgentAutoCloseSubtasks','allowAgentAutoCloseSubtasks','allowAgentAutoCloseSubtasksNote',project.allowAgentAutoCloseSubtasks)}<div class="form-error" hidden></div><button class="button primary" type="submit">${t('saveAutomation')}</button></form>`,()=>{$('#projectPolicyDrawerForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),data=new FormData(form),error=$('.form-error',form);button.disabled=true;try{await api(`/api/projects/${project.id}`,{method:'PATCH',body:JSON.stringify({allowAgentExecution:data.has('allowAgentExecution'),allowAgentAutoClose:data.has('allowAgentAutoClose'),allowSubtasks:data.has('allowSubtasks'),allowAgentAutoCloseSubtasks:data.has('allowAgentAutoCloseSubtasks')})});await loadProjects();closeDrawer();renderProjectSettingsPage()}catch(x){error.textContent=x.message;error.hidden=false;button.disabled=false}}});
}

function projectPromptSegmentDrawer(project,index=null){
  const prompts=[...(project.agentPrompts||[])],value=index===null?'':prompts[index]||'';
  openDrawer(t(index===null?'addPromptSegment':'editPromptSegment'),`<form class="form" id="projectPromptSegmentForm">${area(t('promptContent'),'prompt',value,`required placeholder="${escapeHTML(t('promptPlaceholder'))}"`)}<div class="form-error" hidden></div><button class="button primary" type="submit">${t(index===null?'addPromptSegment':'save')}</button></form>`,()=>{$('#projectPromptSegmentForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),error=$('.form-error',form),prompt=String(new FormData(form).get('prompt')||'').trim();button.disabled=true;try{if(index===null)prompts.push(prompt);else prompts[index]=prompt;await api(`/api/projects/${project.id}`,{method:'PATCH',body:JSON.stringify({agentPrompts:prompts})});await loadProjects();closeDrawer();renderProjectSettingsPage()}catch(x){error.textContent=x.message;error.hidden=false;button.disabled=false}}});
}

function deleteProjectPromptSegment(project,index){
  openDrawer(t('deletePromptSegment'),`<form class="form" id="deletePromptSegmentForm"><p class="drawer-note">${t('deletePromptConfirm')}</p><div class="prompt-delete-preview">${escapeHTML((project.agentPrompts||[])[index]||'')}</div><div class="form-error" hidden></div><button class="button danger" type="submit">${t('deletePromptSegment')}</button></form>`,()=>{$('#deletePromptSegmentForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),error=$('.form-error',form),prompts=[...(project.agentPrompts||[])];prompts.splice(index,1);button.disabled=true;try{await api(`/api/projects/${project.id}`,{method:'PATCH',body:JSON.stringify({agentPrompts:prompts})});await loadProjects();closeDrawer();renderProjectSettingsPage()}catch(x){error.textContent=x.message;error.hidden=false;button.disabled=false}}});
}

function projectBranchPolicyDrawer(project){
  openDrawer(t('editBranchPolicy'),`<form class="form" id="projectBranchPolicyForm">${field(t('defaultBranch'),'defaultTargetBranch','text',project.defaultTargetBranch,'required')}${area(t('allowedBranches'),'allowed',(project.allowedTargetBranches||[]).join('\n'),'required')}<div class="form-error" hidden></div><button class="button primary" type="submit">${t('save')}</button></form>`,()=>{$('#projectBranchPolicyForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),error=$('.form-error',form),data=Object.fromEntries(new FormData(form));button.disabled=true;try{await api(`/api/projects/${project.id}`,{method:'PATCH',body:JSON.stringify({defaultTargetBranch:data.defaultTargetBranch,allowedTargetBranches:data.allowed.split(/\s+/).filter(Boolean)})});await loadProjects();closeDrawer();renderProjectSettingsPage()}catch(x){error.textContent=x.message;error.hidden=false;button.disabled=false}}});
}

renderProjectSettingsPage=async function(){
  if(!state.project)return renderQueue();state.projectSettingsTab=state.projectSettingsTab||'automation';let grant=null;const [members,agents]=await Promise.all([api(`/api/projects/${state.project.id}/members`),api(`/api/projects/${state.project.id}/agents`)]);try{grant=await api(`/api/projects/${state.project.id}/repository-grant`)}catch{}
  const project=state.project,enabledMembers=members.filter(member=>member.role),enabledAgents=agents.filter(agent=>agent.enabled),tabs=[['automation','automation'],['repository','repositoryAndBranches'],['members','members'],['agents','agents']];
  let panel='';
  if(state.projectSettingsTab==='automation'){
    const prompts=(project.agentPrompts||[]).map((prompt,index)=>`<article class="project-prompt-segment"><div><strong>${t('promptSegment')} ${index+1}</strong><p>${escapeHTML(prompt)}</p></div><span><button class="text-action" data-edit-prompt="${index}">${t('editPromptSegment')}</button><button class="text-action danger" data-delete-prompt="${index}">${t('deletePromptSegment')}</button></span></article>`).join('')||`<div class="settings-empty-note">${t('notSet')}</div>`;
    panel=`<div class="project-settings-layout"><section class="settings-card project-prompts-card">${settingsCardHead(t('agentCommonPrompts'),t('agentCommonPromptsNote'),`<button class="button primary" id="addProjectPromptSegment">${icon('plus')}${t('addPromptSegment')}</button>`)}<div class="project-prompt-segments">${prompts}</div></section><aside class="settings-card">${settingsCardHead(t('projectPolicy'),t('projectPolicyDescription'),`<button class="button" id="editProjectPolicy">${icon('settings')}${t('editPolicy')}</button>`)}<div class="settings-policy-list">${policySummary('allowAgentExecution',project.allowAgentExecution)}${policySummary('allowAgentAutoClose',project.allowAgentAutoClose)}${policySummary('allowSubtasks',project.allowSubtasks)}${policySummary('allowAgentAutoCloseSubtasks',project.allowAgentAutoCloseSubtasks)}</div></aside></div>`;
  }else if(state.projectSettingsTab==='repository'){
    panel=`<div class="project-settings-layout"><section class="settings-card">${settingsCardHead(t('repositoryAccess'),grant?t('connected'):t('notConnected'),`<button class="button primary" id="gitGrant">${icon('git')}${t('manageGitAccess')}</button>`)}<dl class="settings-summary-rows">${settingsSummaryRow(t('repository'),`<code>${escapeHTML(project.repositoryUrl)}</code>`)}${settingsSummaryRow(t('status'),t(grant?'connected':'notConnected'))}${settingsSummaryRow(t('onDemandCommitSync'),t('onDemand'))}${settingsSummaryRow(t('lastSyncedAt'),grant?.lastSyncAt?taskDate(grant.lastSyncAt):t('notSynced'))}</dl>${grant?`<div class="settings-card-actions"><button class="button" id="syncCommits">${icon('activity')}${t('syncCommits')}</button></div>`:''}</section><aside class="settings-card">${settingsCardHead(t('branchPolicy'),t('version',{version:project.configVersion}),`<button class="button" id="editBranchPolicy">${icon('settings')}${t('editBranchPolicy')}</button>`)}<dl class="settings-summary-rows">${settingsSummaryRow(t('defaultBranch'),`<code>${escapeHTML(project.defaultTargetBranch)}</code>`)}${settingsSummaryRow(t('allowedBranches'),`<code>${escapeHTML((project.allowedTargetBranches||[]).join(', ')||t('notSet'))}</code>`)}</dl><div class="settings-card-actions"><button class="button" id="editProject">${icon('settings')}${t('editProject')}</button></div></aside></div>`;
  }else if(state.projectSettingsTab==='members'){
    panel=`<section class="project-entity-panel"><header><div><h2>${t('projectMembers')}</h2><p>${t('membersDescription')}</p></div><button class="button primary" id="enableMember">${icon('plus')}${t('enableMember')}</button></header>${enabledMembers.map(member=>`<div class="project-entity-row"><span class="task-avatar">${taskAvatar(member.displayName)}</span><span><strong>${escapeHTML(member.displayName)}</strong><small>${escapeHTML(member.username)} · ${t(member.role)}</small></span><span class="project-row-actions"><button class="text-action" data-manage-member="${member.id}">${t('configure')}</button><button class="text-action danger" data-remove-member="${member.id}">${t('removeFromProject')}</button></span></div>`).join('')||`<div class="settings-empty-note">${t('noEnabledMembers')}</div>`}</section>`;
  }else{
    panel=`<section class="project-entity-panel"><header><div><h2>${t('projectAgents')}</h2><p>${t('agentsDescription')}</p></div><button class="button primary" id="enableAgent">${icon('plus')}${t('enableAgent')}</button></header>${enabledAgents.map(agent=>`<div class="project-entity-row"><span class="task-avatar agent">${taskAvatar(agent.name,'A')}</span><span><strong>${escapeHTML(agent.name)}</strong><small>${escapeHTML(agent.purpose||t('noPurpose'))}</small><span class="agent-live-status"><i class="${agent.keyActive?'on':''}"></i>${t(agent.keyActive?'keyEffective':'keyInactive')}<i class="${agent.connected?'on':''}"></i>${t(agent.connected?'sshConnected':'sshDisconnected')}</span></span><span class="project-row-actions"><button class="text-action" data-manage-agent="${agent.id}">${t('configure')}</button><button class="text-action danger" data-remove-agent="${agent.id}">${t('removeFromProject')}</button></span></div>`).join('')||`<div class="settings-empty-note">${t('noEnabledAgents')}</div>`}</section>`;
  }
  $('#workspace').innerHTML=header(t('projectSettings'),escapeHTML(project.name))+`<div class="content project-settings-page"><nav class="project-settings-tabs" aria-label="${t('projectSettings')}">${tabs.map(([key,label])=>`<button class="${state.projectSettingsTab===key?'active':''}" data-project-tab="${key}">${t(label)}</button>`).join('')}</nav><div class="project-settings-panel">${panel}</div></div>`;
  document.querySelectorAll('[data-project-tab]').forEach(button=>button.onclick=()=>{state.projectSettingsTab=button.dataset.projectTab;renderProjectSettingsPage()});
  $('#addProjectPromptSegment')?.addEventListener('click',()=>projectPromptSegmentDrawer(project));$('#editProjectPolicy')?.addEventListener('click',()=>projectPolicyDrawer(project));document.querySelectorAll('[data-edit-prompt]').forEach(button=>button.onclick=()=>projectPromptSegmentDrawer(project,Number(button.dataset.editPrompt)));document.querySelectorAll('[data-delete-prompt]').forEach(button=>button.onclick=()=>deleteProjectPromptSegment(project,Number(button.dataset.deletePrompt)));$('#gitGrant')?.addEventListener('click',grantForm);$('#editBranchPolicy')?.addEventListener('click',()=>projectBranchPolicyDrawer(project));$('#editProject')?.addEventListener('click',()=>editProjectForm(project));const sync=$('#syncCommits');if(sync)sync.onclick=async()=>{sync.disabled=true;try{const result=await api(`/api/projects/${project.id}/sync-commits`,{method:'POST',body:'{}'});toast(result.skipped==='no_work_items'?t('noWorkItemsSync'):result.skipped==='no_commits'?t('noCommitsSync'):t('syncResult',{fetched:result.fetched,inserted:result.inserted}));await renderProjectSettingsPage()}catch(error){toast(error.message)}finally{sync.disabled=false}};$('#enableMember')?.addEventListener('click',()=>memberEnablePicker(members));$('#enableAgent')?.addEventListener('click',()=>agentEnablePicker(agents));document.querySelectorAll('[data-manage-member]').forEach(button=>button.onclick=()=>memberSettings(members.find(member=>member.id===button.dataset.manageMember)));document.querySelectorAll('[data-remove-member]').forEach(button=>button.onclick=()=>confirmProjectRemoval('member',members.find(member=>member.id===button.dataset.removeMember)));document.querySelectorAll('[data-manage-agent]').forEach(button=>button.onclick=()=>agentSettings(agents.find(agent=>agent.id===button.dataset.manageAgent)));document.querySelectorAll('[data-remove-agent]').forEach(button=>button.onclick=()=>confirmProjectRemoval('agent',agents.find(agent=>agent.id===button.dataset.removeAgent)));
};

function systemAddressDrawer(value){openDrawer(t('editSystemAddress'),`<form class="form" id="systemAddressDrawerForm">${field('ProjectBoard URL','publicUrl','url',value,'required')}<p class="drawer-note">${t('providerReturnOnly')}</p><div class="form-error" hidden></div><button class="button primary" type="submit">${t('save')}</button></form>`,()=>{$('#systemAddressDrawerForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type=submit]',form),error=$('.form-error',form);button.disabled=true;try{await api('/api/system/settings',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(form)))});closeDrawer();toast(t('systemSettingsSaved'));renderSystemSettings()}catch(x){error.textContent=x.message;error.hidden=false;button.disabled=false}}})}

renderSystemSettings=async function(){
  const [settings,sshInfo,providers]=await Promise.all([api('/api/system/settings'),api('/api/system/ssh'),api('/api/git/provider-settings')]),value=settings.publicUrl||location.origin,github=providers.github||{};
  $('#workspace').innerHTML=header(t('globalSettings'),'')+`<div class="content settings-page-shell system-settings-redesign"><section class="settings-card">${settingsCardHead(t('systemAddress'),t('providerReturnOnly'),`<button class="button" id="editSystemAddress">${icon('settings')}${t('editSystemAddress')}</button>`)}<dl class="settings-summary-rows">${settingsSummaryRow('ProjectBoard URL',`<code>${escapeHTML(value)}</code>`)}${settingsSummaryRow(t('status'),t(settings.publicUrl?'configured':'notSaved'))}</dl></section><section class="settings-card">${settingsCardHead('Agent SSH',t('agentSecurityState'))}<dl class="settings-summary-rows">${settingsSummaryRow(t('address'),`<code>${escapeHTML(sshInfo.host)}:${escapeHTML(sshInfo.port)}</code>`)}${settingsSummaryRow(t('fingerprint'),`<code>${escapeHTML(sshInfo.hostKeyFingerprint)}</code>`)}</dl><div class="settings-card-actions"><a class="button" href="/docs/agent-execution.md" target="_blank" rel="noopener">${t('openAgentGuide')}</a></div></section><section class="settings-card">${settingsCardHead(t('githubApp'),t('secureCredentials'),`<button class="button" id="configureGithubApp">${icon('settings')}${t('viewConfiguration')}</button>`)}<dl class="settings-summary-rows">${settingsSummaryRow(t('status'),t(github.configured?'configured':'setupRequired'))}${settingsSummaryRow(t('repositoryContentsRW'),t('write'))}${settingsSummaryRow('Webhook',t('disabled'))}</dl></section></div>`;
  $('#editSystemAddress').onclick=()=>systemAddressDrawer(value);$('#configureGithubApp').onclick=()=>providerSettingsForm('github',github);
};

