function decorateSettingsManagement(section,content){
  const list=content.querySelector(section==='agentsManagement'?'.agent-fleet':'.table');if(!list)return;content.classList.add('settings-management-content');content.querySelector('.agent-list-note')?.remove();const config={agentsManagement:['executionIdentities','settingsAgentCopy','bot'],users:['organizationAccounts','settingsUserCopy','users'],projects:['allProjects','settingsProjectCopy','grid'],audit:['recentActivity','settingsAuditCopy','activity']}[section],count=list.querySelectorAll('button').length,panel=document.createElement('section');if(!count)list.innerHTML=`<div class="settings-compact-empty">${icon(config[2])}<strong>${t(config[0])}</strong><p>${t(section==='audit'?'noActivity':section==='projects'?'noProjectsNote':section==='users'?'usersDescription':'agentKeyNote')}</p></div>`;panel.className='settings-card settings-management-card';panel.innerHTML=settingsCardHead(t(config[0]),t(config[1]),badge(String(count)),config[2])+`<div class="settings-list-toolbar"><label>${icon('search')}<input placeholder="${t('searchCurrentList')}"></label></div>`;panel.append(list);content.append(panel);const input=panel.querySelector('input');input.oninput=()=>list.querySelectorAll('button').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(input.value.toLowerCase()));
}

renderSettingsHub=async function(){
  document.querySelector('.shell')?.classList.add('settings-surface');state.settingsSection=state.settingsSection==='project'?'account':state.settingsSection||'account';const admin=state.me.systemRole==='administrator',sections=[['account','settingsAccount','user'],...(admin?[['agentsManagement','settingsAgents','bot'],['users','settingsUsers','users'],['projects','settingsProjects','grid'],['audit','settingsAudit','activity'],['system','settingsSystem','settings']]:[])],renderer={account:renderAccount,agentsManagement:renderAgentManagement,users:renderUsers,projects:renderProjects,audit:renderActivity,system:renderSystemSettings}[state.settingsSection]||renderAccount;await renderer();const workspace=$('#workspace'),oldHead=workspace.querySelector('.page-head'),content=workspace.querySelector('.content'),info={account:['personalSettings','account','settingsAccountCopy'],agentsManagement:['organizationIdentity','settingsAgents','settingsAgentCopy'],users:['organizationAccess','settingsUsers','settingsUserCopy'],projects:['organizationSpace','settingsProjects','settingsProjectCopy'],audit:['immutableRecords','settingsAudit','settingsAuditCopy'],system:['infrastructure','settingsSystem','settingsSystemCopy']}[state.settingsSection];if(['agentsManagement','users','projects','audit'].includes(state.settingsSection))decorateSettingsManagement(state.settingsSection,content);const wrapper=document.createElement('div');wrapper.className='settings-reference-content global-settings-reference';wrapper.innerHTML=settingsReferenceTabs(sections,state.settingsSection,'settings');const head=document.createElement('div');head.innerHTML=settingsReferenceHead(info[0],info[1],info[2]);const referenceHead=head.firstElementChild,oldActions=oldHead?.querySelector('.page-actions');if(oldActions?.children.length){const actions=document.createElement('div');actions.className='settings-reference-actions';while(oldActions.firstChild)actions.append(oldActions.firstChild);referenceHead.append(actions)}oldHead?.remove();wrapper.append(referenceHead);if(content)wrapper.append(content);workspace.replaceChildren(wrapper);wrapper.querySelectorAll('[data-settings-reference-tab]').forEach(button=>button.onclick=()=>{state.settingsSection=button.dataset.settingsReferenceTab;renderSettingsHub()});
};

/* Unified application surface and shareable client-side routes. */
function projectRouteBase(){return state.project?`/projects/${encodeURIComponent(state.project.key)}`:''}
function currentRouteHash(){
  if(state.page==='settings')return `#/settings/${encodeURIComponent(state.settingsSection||'account')}`;
  const base=projectRouteBase();if(!base)return '#/queue';
  if(state.task)return `#${base}/tasks/${encodeURIComponent(state.task)}`;
  if(state.page==='myQueue')return `#${base}/my-queue`;
  if(state.page==='projectSettings')return `#${base}/settings/${encodeURIComponent(state.projectSettingsTab||'automation')}`;
  if(state.page==='messages')return `#${base}/messages`;
  return `#${base}/queue`;
}
function writeCurrentRoute(replace=false){
  const hash=currentRouteHash();if(location.hash===hash)return;
  history[replace?'replaceState':'pushState']({projectboard:true},'',`${location.pathname}${location.search}${hash}`);
}
function applyRouteFromURL(){
  const parts=location.hash.replace(/^#\/?/,'').split('/').filter(Boolean).map(part=>{try{return decodeURIComponent(part)}catch{return part}});
  state.task=null;
  if(parts[0]==='settings'){
    state.page='settings';state.settingsSection=['account','agentsManagement','users','projects','audit','system'].includes(parts[1])?parts[1]:'account';return;
  }
  if(parts[0]==='projects'){
    const selected=state.projects.find(project=>project.key===parts[1]||project.id===parts[1]);if(selected){state.project=selected;localStorage.pbProject=selected.id}
    if(parts[2]==='tasks'&&parts[3]){state.page='queue';state.task=parts[3];return}
    if(parts[2]==='my-queue'){state.page='myQueue';return}
    if(parts[2]==='settings'){state.page='projectSettings';state.projectSettingsTab=['automation','repository','members','agents'].includes(parts[3])?parts[3]:'automation';return}
    if(parts[2]==='messages'){state.page='messages';return}
    state.page='queue';return;
  }
  if(parts[0]==='my-queue')state.page='myQueue';else if(parts[0]==='messages')state.page='messages';else state.page='queue';
}
navigate=function(page){state.page=page;state.task=null;writeCurrentRoute();renderShell()};
const routedShellRenderer=renderShell;
renderShell=function(){if(!state.routeHydrated){applyRouteFromURL();state.routeHydrated=true}writeCurrentRoute();routedShellRenderer()};
const routedQueueRenderer=renderQueue;
renderQueue=async function(){await routedQueueRenderer();writeCurrentRoute()};
const routedMessageRenderer=renderMessages;
renderMessages=async function(){await routedMessageRenderer();writeCurrentRoute()};
const routedProjectSettingsRenderer=renderProjectSettingsPage;
renderProjectSettingsPage=async function(){await routedProjectSettingsRenderer();writeCurrentRoute()};
const routedSettingsRenderer=renderSettingsHub;
renderSettingsHub=async function(){await routedSettingsRenderer();writeCurrentRoute()};
boot=async function(){syncDocumentLocale();try{state.me=await api('/api/me');await loadProjects();applyRouteFromURL();state.routeHydrated=true;renderShell()}catch{renderLogin()}};
window.addEventListener('popstate',()=>{if(!state.me)return;applyRouteFromURL();renderShell()});

boot();
